window.AUREA_SEARCH = [{"label":"All Components","href":"components.html","group":"Pages","description":"Explore the full list of 149 components, rendered with the Aurea components themselves."},{"label":"Patterns","href":"patterns.html","group":"Pages","description":"234 compositions. A pattern is a component already assembled."},{"label":"Blocks","href":"blocks.html","group":"Pages","description":"15 ready sections. A block is bigger than a pattern and smaller than a page."},{"label":"Recipes","href":"recipes.html","group":"Pages","description":"23 product archetypes: how to assemble a whole kind of application by combining blocks."},{"label":"Hooks","href":"hooks.html","group":"Pages","description":"The public hooks. They are API like any component."},{"label":"Tokens","href":"tokens.html","group":"Pages","description":"The tokens in DTCG format — the single source of the identity."},{"label":"Introduction","href":"getting-started.html","group":"Getting Started","description":"An open-source design system with one look for the web and for React Native, with contrast measured in every theme and brand."},{"label":"Quick Start","href":"docs-quick-start.html","group":"Getting Started","description":"Install the packages, load the fonts before the core, and wrap the app in the provider."},{"label":"Design Principles","href":"docs-design-principles.html","group":"Getting Started","description":"The ten rules behind every Aurea component, and how each one is checked."},{"label":"Frameworks","href":"docs-frameworks.html","group":"Getting Started","description":"Use Aurea with Next.js, Vite, plain HTML or React Native."},{"label":"Showcase","href":"docs-showcase.html","group":"Getting Started","description":"What is built with Aurea today, and how to get your project listed here."},{"label":"Roadmap","href":"docs-roadmap.html","group":"Getting Started","description":"Where Aurea stands, and what has to be true before version 1.0."},{"label":"Colors","href":"docs-colors.html","group":"Getting Started","description":"The color roles of Aurea, what each one is for, and their values in the light and dark themes."},{"label":"Theming","href":"docs-theming.html","group":"Getting Started","description":"How Aurea's tokens become CSS custom properties, the three attributes that switch them, and how to change a value."},{"label":"Dark Mode","href":"docs-dark-mode.html","group":"Getting Started","description":"Switch between the light and dark themes, follow the system, and save the choice."},{"label":"Styling","href":"docs-styling.html","group":"Getting Started","description":"Style Aurea with props first, then with a class name, plain CSS and the tokens."},{"label":"Animation","href":"docs-animation.html","group":"Getting Started","description":"The motion Aurea ships, the tokens behind it, and how it stops when the user asks for less movement."},{"label":"Composition","href":"docs-composition.html","group":"Getting Started","description":"Build bigger pieces from parts, slots, item lists and the render prop."},{"label":"Density","href":"docs-density.html","group":"Getting Started","description":"Three sizes for the same interface, compact, comfortable and spacious, switched with one attribute."},{"label":"Icons","href":"docs-icons.html","group":"Getting Started","description":"The Phosphor icon set, how to serve its sprite, the filled form for the selected item, and how to add your own drawing."},{"label":"RTL","href":"docs-rtl.html","group":"Getting Started","description":"Mirror Aurea for right-to-left languages with two settings, and know what stays in place on purpose."},{"label":"Accessibility","href":"docs-accessibility.html","group":"Getting Started","description":"What Aurea does for contrast, keyboard and screen-reader users, and how each part is checked."},{"label":"LLMs.txt","href":"docs-llms-txt.html","group":"Getting Started","description":"Files that let AI coding assistants read the Aurea documentation."},{"label":"Agent Skills","href":"docs-agent-skills.html","group":"Getting Started","description":"Give your AI coding assistant the rules for building interfaces with Aurea."},{"label":"AGENTS.md","href":"docs-agents-md.html","group":"Getting Started","description":"Short Aurea rules to put in your project's AGENTS.md, for AI coding agents."},{"label":"All Releases","href":"releases.html","group":"Releases","description":"Every update to Aurea: what is new, what changed, what was fixed and what broke."},{"label":"Health","href":"saude.html","group":"Releases"},{"label":"v0.64.0","href":"release-v0-64-0.html","group":"Releases","description":"Checkbox draws the indeterminate state — the \"select all\" of a table with some rows selected — and takes an indeterminate prop."},{"label":"v0.63.0","href":"release-v0-63-0.html","group":"Releases","description":"External links tell screen readers they open in a new tab; one toast region with nested providers; className on SegmentedControl."},{"label":"v0.62.1","href":"release-v0-62-1.html","group":"Releases","description":"Every package README is now in English."},{"label":"v0.62.0","href":"release-v0-62-0.html","group":"Releases","description":"The new Aurea logo, an icon prop on the native IconButton, a horizontal Accordion that opens its first item, and https-only embeds."},{"label":"v0.61.0","href":"release-v0-61-0.html","group":"Releases","description":"Breakpoints follow the browser font size, more selected items in Windows high contrast, and Header passes item clicks."},{"label":"v0.60.0","href":"release-v0-60-0.html","group":"Releases","description":"Selected segments and tabs stay visible in Windows high contrast; code stays left-to-right on right-to-left pages."},{"label":"v0.59.1","href":"release-v0-59-1.html","group":"Releases","description":"The CodeEditor focus ring follows the focus tokens; security headers on the documentation site."},{"label":"v0.59.0","href":"release-v0-59-0.html","group":"Releases","description":"Fixes from an external audit — KPI bars, the native Toast for VoiceOver, ToastHost and BottomNav without SafeAreaProvider."},{"label":"v0.58.0","href":"release-v0-58-0.html","group":"Releases","description":"Motion — the selection slides, menus animate, dragging follows the pointer — DataGrid fit, and recipes as real product screens."},{"label":"v0.57.0","href":"release-v0-57-0.html","group":"Releases","description":"Row dividers, a header pinned to the page, gradients allowed, and five site fixes."},{"label":"v0.56.0","href":"release-v0-56-0.html","group":"Releases","description":"High contrast and large text for the whole app, turned on by the app."},{"label":"v0.55.0","href":"release-v0-55-0.html","group":"Releases","description":"A split button that keeps its round end with the menu open, and menu items with a description and an end icon."},{"label":"v0.54.1","href":"release-v0-54-1.html","group":"Releases","description":"A shorter field for the large CommandPalette."},{"label":"v0.54.0","href":"release-v0-54-0.html","group":"Releases","description":"An example box with the code under the preview, a path and a bar for Stepper, a large CommandPalette, and new options on fourteen web components."},{"label":"v0.53.0","href":"release-v0-53-0.html","group":"Releases","description":"Clickable cards that lift on hover, a framed icon for EmptyState on the web, and the small shadow now shows in the dark theme. Also ships v0.52.1."},{"label":"v0.52.0","href":"release-v0-52-0.html","group":"Releases","description":"The pill on AppShell, a reading ring on TableOfContents and a plus on Accordion — the pieces of the new site."},{"label":"v0.51.0","href":"release-v0-51-0.html","group":"Releases","description":"The far end of the top bar of AppShell — where the theme switch, notifications and the account go."},{"label":"v0.50.0","href":"release-v0-50-0.html","group":"Releases","description":"A dark sidebar on any page — dark on the light theme, darker than the page on the dark one."},{"label":"v0.49.1","href":"release-v0-49-1.html","group":"Releases","description":"On native, a full-width button keeps its size's height, and a long title in the Header no longer pushes the actions off the screen."},{"label":"v0.49.0","href":"release-v0-49-0.html","group":"Releases","description":"The network map lets go of the selected node when you click the empty canvas or press Escape."},{"label":"v0.48.0","href":"release-v0-48-0.html","group":"Releases","description":"Two finishes you can choose — a glow under the primary button and a soft ring around tinted pieces — and a blurred header you can read over anything."},{"label":"v0.47.0","href":"release-v0-47-0.html","group":"Releases","description":"Thirteen brands — Aurea Ember (formerly lory) and eleven new palettes — plus a tighter Toolbar and a red counter on the bottom bar."},{"label":"v0.46.0","href":"release-v0-46-0.html","group":"Releases","description":"New styles for the pressed button, the selected segment, the timeline and the current item of the bottom bar — and a bottom bar of one height in every shape."},{"label":"v0.45.0","href":"release-v0-45-0.html","group":"Releases","description":"The 1.0 palette — zinc neutrals, a graphite accent in light mode, highlighted links, white marks inside controls, white fields everywhere and support for the system's \"increase contrast\"."},{"label":"v0.44.0","href":"release-v0-44-0.html","group":"Releases","description":"The whole sidebar — three ways to collapse, its state outside the AppShell with Ctrl+B, groups that fold, actions, separators, avatars, sections with a panel and five ways to draw the current item."},{"label":"v0.43.0","href":"release-v0-43-0.html","group":"Releases","description":"React Native on the site, with a page for every component; yellow selected states and fixes in React Native; tabs in CodeBlock."},{"label":"v0.42.0","href":"release-v0-42-0.html","group":"Releases","description":"AppShell with the sidebar from top to bottom."},{"label":"v0.41.0","href":"release-v0-41-0.html","group":"Releases","description":"A sidebar with a fixed top and bottom."},{"label":"v0.40.1","href":"release-v0-40-1.html","group":"Releases","description":"The new typeface and the white fields reach React Native."},{"label":"v0.40.0","href":"release-v0-40-0.html","group":"Releases","description":"White fields in the light theme."},{"label":"v0.39.0","href":"release-v0-39-0.html","group":"Releases","description":"A new typeface on the web — Inter for text, Sora for titles and IBM Plex Mono for code."},{"label":"v0.38.0","href":"release-v0-38-0.html","group":"Releases","description":"The legend and the overview of DependencyGraph can step aside, so they no longer cover the devices in the bottom corners."},{"label":"v0.37.1","href":"release-v0-37-1.html","group":"Releases","description":"Wide content no longer widens the page inside DataState, Form and the Dialog body, and field placeholders reach 4.5:1 in the lory brand."},{"label":"v0.37.0","href":"release-v0-37-0.html","group":"Releases","description":"Line numbers and syntax colors for CodeBlock, a brand blue as the accent text in the light theme, and a visible disabled state in seven components."},{"label":"v0.36.0","href":"release-v0-36-0.html","group":"Releases","description":"A page opening for Section, a cookie notice for Banner, Chip as another name for Badge, two larger text tokens, the brand yellow as the accent text in the light theme, and fixes to DependencyGraph and Radio."},{"label":"v0.35.0","href":"release-v0-35-0.html","group":"Releases","description":"A documentation layout for the AppShell, a second row of area tabs in the Header, five docs width tokens, and snapping in the editable DependencyGraph."},{"label":"v0.34.0","href":"release-v0-34-0.html","group":"Releases","description":"No lines. Components no longer draw borders on web or React Native; what needed a border to stand out now gets a translucent fill."},{"label":"v0.33.0","href":"release-v0-33-0.html","group":"Releases","description":"RadioGroup on the web, a three-position ThemeToggle with a system preference, Card parts, soft buttons, a blurred Header, and popups that stay above fixed headers."},{"label":"v0.32.0","href":"release-v0-32-0.html","group":"Releases","description":"Twelve new components, including Slider, ListBox, DatePicker on the web and a full color family; redesigned controls and dialogs; and a 48px touch scale for React Native."},{"label":"v0.31.0","href":"release-v0-31-0.html","group":"Releases","description":"Editing for the DependencyGraph - drag, align and pin nodes, undo, containers that collapse, routed edges, tree and radial layouts, and options for large graphs."},{"label":"v0.30.0","href":"release-v0-30-0.html","group":"Releases","description":"Reading large graphs with the DependencyGraph - vertical layered layout, icons, badges and ports, edges that explain themselves without color, minimap, path highlight and export."},{"label":"v0.29.0","href":"release-v0-29-0.html","group":"Releases","description":"A Card that stands out in both themes, a colored accent strip on top of cards, and a fix for dark sections inside the lory brand."},{"label":"v0.28.0","href":"release-v0-28-0.html","group":"Releases","description":"Share buttons that fall back to copying the link, a phone frame for screenshots, an extra-bold weight and tabular numbers."},{"label":"v0.27.0","href":"release-v0-27-0.html","group":"Releases","description":"New neutral and status colors for both themes, with separate tokens for fills and text. Also ships v0.26.0 (category badges, KPI direction) and v0.26.1."},{"label":"v0.25.0","href":"release-v0-25-0.html","group":"Releases","description":"Focus is drawn as a single line instead of border plus ring, and the selected tab is finally visible against its track."},{"label":"v0.24.1","href":"release-v0-24-1.html","group":"Releases","description":"Fixes the anchored Badge in React Native and the KPI number size on the web, and adds a CSS variable for chart text size."},{"label":"v0.24.0","href":"release-v0-24-0.html","group":"Releases","description":"Comparison tables: sticky header and first column, a two-item mobile fit, a \"differences only\" switch, and styling for groups and best values."},{"label":"v0.23.0","href":"release-v0-23-0.html","group":"Releases","description":"Topbar is renamed Header (the old name still works), with a site header that collapses into a mobile menu, and a site footer section."},{"label":"v0.22.0","href":"release-v0-22-0.html","group":"Releases","description":"Layout parts for site pages (Container, Grid.Item span, Section with surface and theme). Also ships v0.21.0 and v0.20.0."},{"label":"v0.19.1","href":"release-v0-19-1.html","group":"Releases","description":"Fixes square BottomNav indicators on Android. Also ships v0.19.0: lazy TreeView, batch Gallery, attachments and replies in chat, long conversations."},{"label":"v0.18.0","href":"release-v0-18-0.html","group":"Releases","description":"Indeterminate Progress with detail and tone, named Grid minimums, NavList avatars and indicators, and a collapsible AppShell sidebar."},{"label":"v0.17.0","href":"release-v0-17-0.html","group":"Releases","description":"BottomNav no longer shifts when switching tabs, is shorter with labels closer to icons, and gains the capsule and expand indicators."},{"label":"v0.16.1","href":"release-v0-16-1.html","group":"Releases","description":"Fixes the BottomNav circle-bold indicator, which collapsed into a thin line in the browser and cut the label on the compact bar."},{"label":"v0.16.0","href":"release-v0-16-0.html","group":"Releases","description":"In the light theme, emphasis text and icons move from brown to a darkened brand yellow that still meets 4.5:1 contrast."},{"label":"v0.15.0","href":"release-v0-15-0.html","group":"Releases","description":"React Native gets custom icon components in every icon prop, a richer Timeline, a new FileInput, and a PhotoInput that opens the photo."},{"label":"v0.14.1","href":"release-v0-14-1.html","group":"Releases","description":"A busy IconButton now shows only a centred spinner. Also ships v0.14.0, with new React Native props for Tabs, Combobox, NumberField and RadioGroup."},{"label":"v0.13.0","href":"release-v0-13-0.html","group":"Releases","description":"New typeface and icon set. Atkinson Hyperlegible Next replaces IBM Plex, and Phosphor icons replace Carbon. Icon names change."},{"label":"v0.12.4","href":"release-v0-12-4.html","group":"Releases","description":"React Native components running in the browser now expose their state to screen readers through aria attributes."},{"label":"v0.12.3","href":"release-v0-12-3.html","group":"Releases","description":"Adds RadioGroup to React Native, with full-row touch targets and the indicator at the start or end of each row."},{"label":"v0.12.2","href":"release-v0-12-2.html","group":"Releases","description":"The BottomNav is shorter on the web and in React Native, with the icon closer to its label."},{"label":"v0.12.1","href":"release-v0-12-1.html","group":"Releases","description":"React Native fixes for bottom sheets and Grid, plus LinkButton. Also ships v0.12.0 with typed icon names, round icon buttons, ThemeToggle and text components."},{"label":"v0.11.0","href":"release-v0-11-0.html","group":"Releases","description":"React Native fixes for Android (clipped button text, lists that did not scroll, sheets behind system buttons), new Badge sizes and centred Radio and Checkbox marks."},{"label":"v0.10.1","href":"release-v0-10-1.html","group":"Releases","description":"criarGlifo can now draw stroked shapes, so line-drawn logos work in React Native without importing an SVG library."},{"label":"v0.10.0","href":"release-v0-10-0.html","group":"Releases","description":"Web layout additions for Topbar, AppShell, Field and Card, a clearer current item in the Sidebar, and a fix for a stretched top bar."},{"label":"v0.9.0","href":"release-v0-9-0.html","group":"Releases","description":"Layout props for the web primitives, Button, Card, Separator and Dialog. The default Dialog width changes from 560 to 448."},{"label":"v0.8.14","href":"release-v0-8-14.html","group":"Releases","description":"Additive props for Badge, Cluster, Topbar and Screen, a shared disabled-opacity token, and criarGlifo for custom glyphs in React Native."},{"label":"v0.8.13","href":"release-v0-8-13.html","group":"Releases","description":"The React Native Card responds to taps with onPress, and the BottomNav can size itself to its tabs with width=\"content\"."},{"label":"v0.8.12","href":"release-v0-8-12.html","group":"Releases","description":"A new type scale (12 to 48). Web components return to 14 pixels, while React Native components use 16."},{"label":"v0.8.11","href":"release-v0-8-11.html","group":"Releases","description":"Adds MediaEmbed, which shows a video from another site (YouTube, Vimeo) in Aurea's frame, with an optional poster that loads nothing until clicked."},{"label":"v0.8.10","href":"release-v0-8-10.html","group":"Releases","description":"Select gets Aurea's own skin and floating list instead of the browser's native control. Also ships v0.8.9, with navItems on AppShell and labelWidth on Field."},{"label":"v0.8.8","href":"release-v0-8-8.html","group":"Releases","description":"Web fixes for Combobox, the mobile drawer, DependencyGraph and DataGrid, React Native fixes found on Android, BottomNavProvider, and a new type scale."},{"label":"v0.8.7","href":"release-v0-8-7.html","group":"Releases","description":"In React Native, the brand Card now keeps its fields, buttons and focus readable on the yellow, and menus or sheets opened from inside it no longer inherit its colors."},{"label":"v0.8.6","href":"release-v0-8-6.html","group":"Releases","description":"React Native gets a yellow brand Card that requires an action, and SegmentedControl and Tabs now scroll sideways with a visible hint when the options do not fit."},{"label":"v0.8.5","href":"release-v0-8-5.html","group":"Releases","description":"React Native gets Tabs, new props on Badge, Switch and NavList, and fixes for controls that VoiceOver on iPhone could not reach."},{"label":"v0.8.4","href":"release-v0-8-4.html","group":"Releases","description":"In React Native, the Combobox clear button is reachable by VoiceOver on iPhone, and the arrow now opens the list."},{"label":"v0.8.3","href":"release-v0-8-3.html","group":"Releases","description":"React Native fixes for brand and destructive text contrast and for Input dropping props, plus Separator, a link tone on Text and new PasswordField props."},{"label":"v0.8.2","href":"release-v0-8-2.html","group":"Releases","description":"React Native gets InputGroup, InputGroupAddon and PasswordField, and Button accepts any drawing in leading and trailing."},{"label":"v0.8.1","href":"release-v0-8-1.html","group":"Releases","description":"React Native fixes for NumberField focus and width, the Combobox sheet hidden behind the iOS keyboard, and hard-coded sheet heights."},{"label":"v0.8.0","href":"release-v0-8-0.html","group":"Releases","description":"Five new React Native components (Combobox, SearchField, NumberField, Image and Gallery), number formatting helpers and new strings, with no new dependencies."},{"label":"v0.7.0","href":"release-v0-7-0.html","group":"Releases","description":"The first release of @aurea-uds/native, with 46 React Native components, plus fixes for crashing accessibility roles and a theme switch that got out of sync on the web."},{"label":"v0.6.0","href":"release-v0-6-0.html","group":"Releases","description":"Nine new web components, menus with submenus, checkboxes and radio groups, new hooks, and one breaking change: size on field components is now sm, md or lg."},{"label":"v0.5.0","href":"release-v0-5-0.html","group":"Releases","description":"Brands arrive as a second axis next to the theme, starting with lory, and the sidebar now paints itself with its own tokens."},{"label":"v0.4.0","href":"release-v0-4-0.html","group":"Releases","description":"BottomNav, NavList and Separator arrive, Badge is rewritten, Sidebar gains a flush variant, and Button's pressed prop is deprecated in favor of Toggle."},{"label":"v0.3.0","href":"release-v0-3-0.html","group":"Releases","description":"Eleven new components, including BlockEditor, Carousel, CommandPalette and Form, server rendering for 22 markup components, a React Native token target and accessibility fixes in Field and Toggle."},{"label":"v0.2.0","href":"release-v0-2-0.html","group":"Releases","description":"React Server Components support, 27 new components including a new AI and Agents category, a server-backed DataGrid, universal states and five breaking changes."},{"label":"v0.1.0","href":"release-v0-1-0.html","group":"Releases","description":"The first public release of Aurea UDS, published as six packages on npm."},{"label":"AccessGate","href":"accessgate.html","group":"Components","description":"Hides an action the user cannot take, or shows it inert with the reason.","icon":"lock"},{"label":"Accordion","href":"accordion.html","group":"Components","description":"Stack of expandable/collapsible sections.","icon":"caret-down","native":"native-accordion.html"},{"label":"AgentCard","href":"agentcard.html","group":"Components","description":"Who an agent is, what state it is in, and what it can do.","icon":"user-circle"},{"label":"AgentInspector","href":"agentinspector.html","group":"Components","description":"The detail of one agent: configuration, tools, instructions.","icon":"gear"},{"label":"AgentStatus","href":"agentstatus.html","group":"Components","description":"The state of an agent, in one fixed vocabulary.","icon":"pulse"},{"label":"Alert","href":"alert.html","group":"Components","description":"Inline message that stays in context.","icon":"warning","native":"native-alert.html"},{"label":"AppShell","href":"appshell.html","group":"Components","description":"Application frame: sidebar, topbar and main content.","icon":"squares-four"},{"label":"AspectRatio","href":"aspectratio.html","group":"Components","description":"A box that keeps its proportion, whatever the width.","icon":"arrows-in-simple"},{"label":"AureaProvider","href":"aureaprovider.html","group":"Components","description":"Root provider: strings, icon sprite, text direction, toasts and where popups mount.","icon":"gear","native":"native-aureaprovider.html"},{"label":"AutomationCard","href":"automationcard.html","group":"Components","description":"A rule that runs on its own: when this, then that — and a switch.","icon":"flow-arrow"},{"label":"Avatar","href":"avatar.html","group":"Components","description":"Represents a user or entity with image or initials.","icon":"user-circle","native":"native-avatar.html"},{"label":"AvatarGroup","href":"avatargroup.html","group":"Components","description":"Overlapping stack of avatars, with a count for the ones that do not fit.","icon":"users"},{"label":"Badge","href":"badge.html","group":"Components","description":"Short metadata label or status marker.","icon":"tag","native":"native-badge.html"},{"label":"Banner","href":"banner.html","group":"Components","description":"Prominent message spanning a wide region. variant=\"consent\" is the cookie notice, with the preferences window.","icon":"bell"},{"label":"BlockEditor","href":"blockeditor.html","group":"Components","description":"The frame around content blocks — order, handle, removal, and the slot where your own editor goes. Aurea does not own the rich text.","icon":"file-text"},{"label":"BottomNav","href":"bottomnav.html","group":"Components","description":"Floating bar pinned to the bottom that holds an application's top-level navigation.","icon":"list","native":"native-bottomnav.html"},{"label":"Breadcrumb","href":"breadcrumb.html","group":"Components","description":"Trail showing the current location in a hierarchy.","icon":"tree-view"},{"label":"Button","href":"button.html","group":"Components","description":"Trigger for an action or navigation. The primary interactive control.","icon":"plus","native":"native-button.html"},{"label":"ButtonGroup","href":"buttongroup.html","group":"Components","description":"Buttons joined into one capsule — no gap, rounded only at the ends, a hairline between them — that share their variant, size and disabled state.","icon":"squares-four"},{"label":"Calendar","href":"calendar.html","group":"Components","description":"Month grid for picking a day, a range, or several days.","icon":"calendar"},{"label":"Card","href":"card.html","group":"Components","description":"Floating surface that groups related content.","icon":"books","native":"native-card.html"},{"label":"Carousel","href":"carousel.html","group":"Components","description":"Slides that snap, with arrows and dots. The scroll container is the engine.","icon":"image"},{"label":"Chart","href":"chart.html","group":"Components","description":"Sized, named surface that hosts a Recharts chart wearing Aurea tokens.","icon":"chart-line","native":"native-chart.html"},{"label":"ChartLegend","href":"chartlegend.html","group":"Components","description":"Which colour is which series, as a plain list under the chart.","icon":"chart-bar","native":"native-chartlegend.html"},{"label":"ChartTooltip","href":"charttooltip.html","group":"Components","description":"Values under the pointer, on the same tooltip surface as the rest of Aurea.","icon":"chart-line"},{"label":"Checkbox","href":"checkbox.html","group":"Components","description":"Binary or tri-state selection control.","icon":"check","native":"native-checkbox.html"},{"label":"CheckboxGroup","href":"checkboxgroup.html","group":"Components","description":"A group of checkboxes with a label, a description and an error, that keeps the list of what is checked.","icon":"list-checks"},{"label":"Chip","href":"chip.html","group":"Components","description":"Another name for Badge, for those who know this piece as a chip. Identical in everything: the same props, the same look, the same behaviour.","icon":"tag","native":"native-chip.html"},{"label":"CloseButton","href":"closebutton.html","group":"Components","description":"The round close button: a 24 circle on the neutral fill with a 16 X in the Bold stroke, named \"Close\" by itself.","icon":"x","native":"native-closebutton.html"},{"label":"Cluster","href":"cluster.html","group":"Components","description":"Horizontal wrapping/layout primitive.","icon":"dots-six","native":"native-cluster.html"},{"label":"Code","href":"code.html","group":"Components","description":"A short piece of code inside a sentence. For a block of code use CodeBlock.","icon":"code","native":"native-code.html"},{"label":"CodeBlock","href":"codeblock.html","group":"Components","description":"Read-only code display, with line numbers and syntax colors when you pass the highlighter.","icon":"code-block"},{"label":"CodeEditor","href":"codeeditor.html","group":"Components","description":"Editable code surface.","icon":"code"},{"label":"Collapsible","href":"collapsible.html","group":"Components","description":"One section that opens and closes, with the open state owned by the app.","icon":"caret-down"},{"label":"ColorArea","href":"colorarea.html","group":"Components","description":"The square where you pick two channels of a colour for the third one fixed — saturation and brightness by default, or any pair of HSB, HSL or RGB — by pointer, touch or keyboard. The screen reader hears the channels and the colour's name.","icon":"palette"},{"label":"ColorField","href":"colorfield.html","group":"Components","description":"A field for a colour: the swatch in front and the code — hex, rgb(), hsl() or hsb() — applied on Enter or when it loses focus; or one channel as a number. Inside a Field, the label, description and error are the Field's.","icon":"palette"},{"label":"ColorPicker","href":"colorpicker.html","group":"Components","description":"A swatch with a name that opens a window to pick a colour: the area, the hue track and the hex field — or, as the swatches variation, a closed palette with the hex field.","icon":"palette"},{"label":"ColorSwatch","href":"colorswatch.html","group":"Components","description":"A round sample of a colour, with a thin inner ring so a colour the same as the background still shows, and a checkerboard under a transparent colour. With options, a group of swatches to pick one from (a closed palette).","icon":"palette"},{"label":"Combobox","href":"combobox.html","group":"Components","description":"Text field with an autocomplete listbox.","icon":"magnifying-glass","native":"native-combobox.html"},{"label":"CommandPalette","href":"commandpalette.html","group":"Components","description":"The command palette with the engine wired up: type, filter, run.","icon":"magnifying-glass"},{"label":"CommandPaletteShell","href":"commandpaletteshell.html","group":"Components","description":"Overlay shell for a searchable command palette.","icon":"terminal"},{"label":"ConfirmDialog","href":"confirmdialog.html","group":"Components","description":"Alert dialog for a decision that cannot be taken back.","icon":"warning","native":"native-confirmdialog.html"},{"label":"Container","href":"container.html","group":"Components","description":"The reading width of a website page: centred, capped, with side gutters that grow with the screen.","icon":"ruler"},{"label":"ContainerScope","href":"containerscope.html","group":"Components","description":"Declares an Aurea container: the box that container-responsive values measure themselves against.","icon":"arrows-out"},{"label":"ContextMenu","href":"contextmenu.html","group":"Components","description":"Actions menu opened by right-click or long-press.","icon":"list"},{"label":"CostMeter","href":"costmeter.html","group":"Components","description":"Spend against a ceiling, with the soft and hard limits kept apart.","icon":"gauge"},{"label":"DataGrid","href":"datagrid.html","group":"Components","description":"Interactive grid with navigation, sort and selection.","icon":"table"},{"label":"DataList","href":"datalist.html","group":"Components","description":"Key/value or item list for structured data.","icon":"list-bullets","native":"native-datalist.html"},{"label":"DataState","href":"datastate.html","group":"Components","description":"One region, four faces: loading, failed, empty, or the content itself.","icon":"table","native":"native-datastate.html"},{"label":"DatePicker","href":"datepicker.html","group":"Components","description":"A field that opens a calendar to pick a date, or a range of dates.","icon":"calendar","native":"native-datepicker.html"},{"label":"DependencyGraph","href":"dependencygraph.html","group":"Components","description":"Who depends on whom, on a canvas you can pan, zoom and build on.","icon":"flow-arrow"},{"label":"Dialog","href":"dialog.html","group":"Components","description":"Modal surface that interrupts for a focused task.","icon":"arrows-out","native":"native-dialog.html"},{"label":"Drawer","href":"drawer.html","group":"Components","description":"Panel that slides in from a screen edge.","icon":"sidebar-simple","native":"native-drawer.html"},{"label":"DropdownMenu","href":"dropdownmenu.html","group":"Components","description":"Menu of actions triggered by a control.","icon":"dots-three","native":"native-dropdownmenu.html"},{"label":"EmptyState","href":"emptystate.html","group":"Components","description":"Placeholder for an empty or zero-result view.","icon":"folder-open","native":"native-emptystate.html"},{"label":"EventStream","href":"eventstream.html","group":"Components","description":"What happened, in order, live.","icon":"pulse"},{"label":"Field","href":"field.html","group":"Components","description":"Form-field wrapper: label, control, description and error.","icon":"file","native":"native-field.html"},{"label":"FileInput","href":"fileinput.html","group":"Components","description":"Upload control with progress and validation.","icon":"upload","native":"native-fileinput.html"},{"label":"Form","href":"form.html","group":"Components","description":"Shows the error and collects the values. It does not decide what an error is.","icon":"file-text","native":"native-form.html"},{"label":"Gallery","href":"gallery.html","group":"Components","description":"A grid of pictures you can pick from, and enlarge in the dialog that already exists.","icon":"image","native":"native-gallery.html"},{"label":"Grid","href":"grid.html","group":"Components","description":"Two-dimensional layout primitive.","icon":"grid-four","native":"native-grid.html"},{"label":"Header","href":"header.html","group":"Components","description":"The top bar of an app or a website — also called header, navbar or top bar. Brand, the site's links with the current page marked, actions, and on a phone a menu button that drops the links below the bar.","icon":"list","native":"native-header.html"},{"label":"Heading","href":"heading.html","group":"Components","description":"A heading, h1 to h6. The level picks both the element and the size, as in the reference library.","icon":"file-text","native":"native-heading.html"},{"label":"HealthMatrix","href":"healthmatrix.html","group":"Components","description":"What is up, in a grid.","icon":"table"},{"label":"HoverCard","href":"hovercard.html","group":"Components","description":"Rich preview that opens when the pointer rests on a link, and whose content can be reached.","icon":"user-circle"},{"label":"HumanApproval","href":"humanapproval.html","group":"Components","description":"The gate: what is about to happen, and a person's decision.","icon":"ruler"},{"label":"Icon","href":"icon.html","group":"Components","description":"Icon primitive rendered from a sprite.","icon":"palette","native":"native-icon.html"},{"label":"IconButton","href":"iconbutton.html","group":"Components","description":"Icon-only button with a required accessible label.","icon":"arrows-out","native":"native-iconbutton.html"},{"label":"Image","href":"image.html","group":"Components","description":"An image that reserves its box before the bytes arrive, and falls back when they never do.","icon":"image","native":"native-image.html"},{"label":"Input","href":"input.html","group":"Components","description":"Single-line text entry control.","icon":"pencil-simple","native":"native-input.html"},{"label":"InputGroup","href":"inputgroup.html","group":"Components","description":"The box that looks like a field and holds the control plus whatever is glued to it.","icon":"link","native":"native-inputgroup.html"},{"label":"InputGroupAddon","href":"inputgroupaddon.html","group":"Components","description":"What sits glued to the control inside an InputGroup: a glyph, a prefix, a button.","icon":"plus","native":"native-inputgroupaddon.html"},{"label":"InterAgentMessage","href":"interagentmessage.html","group":"Components","description":"A message from one agent to another, where the direction is the data.","icon":"paper-plane-tilt"},{"label":"InvocationPanel","href":"invocationpanel.html","group":"Components","description":"One execution: what was asked, the steps, what came out.","icon":"flow-arrow"},{"label":"Kbd","href":"kbd.html","group":"Components","description":"A keyboard key or shortcut, shown as the user would press it. Renders the <kbd> element.","icon":"keyboard"},{"label":"KPI","href":"kpi.html","group":"Components","description":"Single headline metric with optional delta.","icon":"chart-line-up","native":"native-kpi.html"},{"label":"Label","href":"label.html","group":"Components","description":"The field label on its own, for when you are not using Field.","icon":"tag","native":"native-label.html"},{"label":"Link","href":"link.html","group":"Components","description":"A text link: medium weight in the link colour, no underline until hovered; external opens in a new tab with the arrow.","icon":"link"},{"label":"ListBox","href":"listbox.html","group":"Components","description":"A standalone list of options with sections, descriptions and icons — choose none, one or many, or use it as a list of actions.","icon":"list-bullets"},{"label":"LogStream","href":"logstream.html","group":"Components","description":"Live-appending stream of log lines.","icon":"terminal"},{"label":"MediaEmbed","href":"mediaembed.html","group":"Components","description":"A third-party video page (YouTube, Vimeo) inside the Aurea frame, loaded only when asked for.","icon":"video-camera"},{"label":"MediaPlayer","href":"mediaplayer.html","group":"Components","description":"Video/audio player with full controls.","icon":"play"},{"label":"MediaPlayerShell","href":"mediaplayershell.html","group":"Components","description":"Layout shell hosting a media player and its chrome.","icon":"video-camera"},{"label":"MemoryLedger","href":"memoryledger.html","group":"Components","description":"What the agent stored, recalled or forgot — and where it came from.","icon":"notebook"},{"label":"Menubar","href":"menubar.html","group":"Components","description":"The application menu row — File, Edit, View — where an open menu hands over to its neighbour.","icon":"list"},{"label":"MessageComposer","href":"messagecomposer.html","group":"Components","description":"Input surface for composing a message.","icon":"paper-plane-tilt"},{"label":"MessageList","href":"messagelist.html","group":"Components","description":"Scrolling list of conversation messages.","icon":"chat"},{"label":"ModelUsage","href":"modelusage.html","group":"Components","description":"Consumption split by model: which one took how much.","icon":"chart-bar"},{"label":"MultiCombobox","href":"multicombobox.html","group":"Components","description":"Combobox that accepts multiple selected values.","icon":"list-checks"},{"label":"NavList","href":"navlist.html","group":"Components","description":"A list of tappable rows that open something: leading icon, label, an optional second line, an optional trailing value, and the chevron that says \"this goes somewhere\". The brick of every settings screen.","icon":"list-bullets","native":"native-navlist.html"},{"label":"NotificationCenter","href":"notificationcenter.html","group":"Components","description":"Inbox surface aggregating notifications.","icon":"bell-ringing"},{"label":"NumberField","href":"numberfield.html","group":"Components","description":"Numeric field with decrease and increase controls, for a quantity you nudge.","icon":"plus","native":"native-numberfield.html"},{"label":"OTPField","href":"otpfield.html","group":"Components","description":"One box per character, for a verification code the user types or pastes.","icon":"password","native":"native-otpfield.html"},{"label":"Pagination","href":"pagination.html","group":"Components","description":"Navigate across pages of content.","icon":"arrow-right"},{"label":"Paragraph","href":"paragraph.html","group":"Components","description":"A paragraph of body text in one of three sizes.","icon":"file-text","native":"native-paragraph.html"},{"label":"PasswordField","href":"passwordfield.html","group":"Components","description":"A password field with a show/hide control that announces what it does.","icon":"password","native":"native-passwordfield.html"},{"label":"Popover","href":"popover.html","group":"Components","description":"Anchored floating surface with content or interaction.","icon":"info","native":"native-popover.html"},{"label":"Progress","href":"progress.html","group":"Components","description":"Progress bar: determinate, or indeterminate when the total is not known yet, with a supporting detail and a tone.","icon":"spinner","native":"native-progress.html"},{"label":"ProgressCircle","href":"progresscircle.html","group":"Components","description":"Progress as a ring that fills from the top; without a value it spins.","icon":"circle-notch"},{"label":"Prose","href":"prose.html","group":"Components","description":"The skin for long-form text. It is not the parser — that stays yours.","icon":"file-text"},{"label":"QRCode","href":"qrcode.html","group":"Components","description":"Scannable QR code rendered as a styled SVG with Aurea soft geometry.","icon":"grid-four"},{"label":"Radio","href":"radio.html","group":"Components","description":"Single choice within a group.","icon":"hourglass","native":"native-radio.html"},{"label":"RadioGroup","href":"radiogroup.html","group":"Components","description":"A group of radio options with a label, a description and an error, that keeps the chosen value — vertical or horizontal. RadioGroup.Item is the Radio.","icon":"check-circle","native":"native-radiogroup.html"},{"label":"Range","href":"range.html","group":"Components","description":"Slider for selecting a value from a range.","icon":"gauge"},{"label":"SearchField","href":"searchfield.html","group":"Components","description":"Text field specialized for search, with clear affordance.","icon":"magnifying-glass","native":"native-searchfield.html"},{"label":"Section","href":"section.html","group":"Components","description":"An edge-to-edge band of a website page, with its own surface, site spacing and, optionally, its own theme. variant=\"footer\" makes it the site's footer; variant=\"hero\" makes it the page opening.","icon":"list"},{"label":"SegmentedControl","href":"segmentedcontrol.html","group":"Components","description":"Choose one option from a compact inline set.","icon":"squares-four","native":"native-segmentedcontrol.html"},{"label":"Select","href":"select.html","group":"Components","description":"Choose a single value from a closed list, in the Aurea skin.","icon":"caret-down","native":"native-select.html"},{"label":"Separator","href":"separator.html","group":"Components","description":"A rule between things. Horizontal or vertical, one hairline in the border colour — the thing a sidebar uses between sections and a toolbar uses between groups.","icon":"minus","native":"native-separator.html"},{"label":"Sidebar","href":"sidebar.html","group":"Components","description":"Floating side panel that holds the application's navigation.","icon":"sidebar-simple"},{"label":"Skeleton","href":"skeleton.html","group":"Components","description":"Placeholder shown while content loads.","icon":"hourglass","native":"native-skeleton.html"},{"label":"Slider","href":"slider.html","group":"Components","description":"Drawn slider: label and value on top, a 20 track with the fill, a capsule thumb. One value or a range of two, horizontal or vertical, number formatted by Intl.","icon":"faders","native":"native-slider.html"},{"label":"SortableList","href":"sortablelist.html","group":"Components","description":"Reorder by dragging — and by keyboard, which is the reason it may exist at all.","icon":"dots-six"},{"label":"Spinner","href":"spinner.html","group":"Components","description":"Indeterminate activity indicator for a wait with no known end.","icon":"arrows-clockwise","native":"native-spinner.html"},{"label":"Stack","href":"stack.html","group":"Components","description":"Vertical spacing/layout primitive.","icon":"list-bullets","native":"native-stack.html"},{"label":"Status","href":"status.html","group":"Components","description":"Operational condition of a thing: a coloured dot plus a readable label.","icon":"wifi-high","native":"native-status.html"},{"label":"Stepper","href":"stepper.html","group":"Components","description":"Progress through numbered steps, for a task that happens in a fixed order.","icon":"circle-notch","native":"native-stepper.html"},{"label":"Switch","href":"switch.html","group":"Components","description":"On/off toggle.","icon":"power","native":"native-switch.html"},{"label":"Table","href":"table.html","group":"Components","description":"Presents rows and columns of data — also a comparison table: groups of rows, the row's name pinned while scrolling sideways, the header pinned while scrolling down, the best value marked and a 'differences only' switch. Every cell has tabular figures, so price and year columns line up.","icon":"tree-structure","native":"native-table.html"},{"label":"TableOfContents","href":"tableofcontents.html","group":"Components","description":"In-page index of a document's sections. Sticky beside the content, marks the section in view.","icon":"list-bullets"},{"label":"Tabs","href":"tabs.html","group":"Components","description":"Switch between peer views in the same context.","icon":"squares-four","native":"native-tabs.html"},{"label":"TagGroup","href":"taggroup.html","group":"Components","description":"A wrapping row of tags with a label: none, one or several can be selected, and each can be removed.","icon":"tag","native":"native-taggroup.html"},{"label":"TaskQueue","href":"taskqueue.html","group":"Components","description":"The work queue: what is waiting, what is running, what failed.","icon":"list-bullets"},{"label":"Text","href":"text.html","group":"Components","description":"Text in one of a closed list of roles — a heading level, body text or code — never a loose size. The reference library's Typography model.","icon":"file-text","native":"native-text.html"},{"label":"Textarea","href":"textarea.html","group":"Components","description":"Multi-line text entry control.","icon":"file-text","native":"native-textarea.html"},{"label":"ThemeToggle","href":"themetoggle.html","group":"Components","description":"The light/dark switch, with colour in the glyph: a dark moon in the light theme, the brand yellow sun in the dark one.","icon":"arrows-out","native":"native-themetoggle.html"},{"label":"Timeline","href":"timeline.html","group":"Components","description":"Chronological sequence of events.","icon":"clock","native":"native-timeline.html"},{"label":"Toggle","href":"toggle.html","group":"Components","description":"Two-state button that stays pressed, for a setting you flip in place.","icon":"check"},{"label":"ToggleGroup","href":"togglegroup.html","group":"Components","description":"Several toggles sharing one state, with arrow-key navigation between them.","icon":"list-bullets"},{"label":"Toolbar","href":"toolbar.html","group":"Components","description":"Container of actions with roving-tabindex keyboard navigation.","icon":"gear"},{"label":"ToolbarButton","href":"toolbarbutton.html","group":"Components","description":"Button tuned for use inside a Toolbar.","icon":"check-square"},{"label":"ToolbarGroup","href":"toolbargroup.html","group":"Components","description":"Structural grouping of toolbar items.","icon":"list-bullets"},{"label":"ToolbarSeparator","href":"toolbarseparator.html","group":"Components","description":"Visual divider between toolbar groups.","icon":"minus"},{"label":"ToolPermission","href":"toolpermission.html","group":"Components","description":"What each tool may do, without asking again.","icon":"password"},{"label":"Tooltip","href":"tooltip.html","group":"Components","description":"Brief label revealed on hover or focus.","icon":"question"},{"label":"Topbar","href":"topbar.html","group":"Components","description":"The old name of Header. Same component, still works the same; use Header.","icon":"list","native":"native-topbar.html"},{"label":"TraceTimeline","href":"tracetimeline.html","group":"Components","description":"How long each step took, as a waterfall.","icon":"gauge"},{"label":"TreeView","href":"treeview.html","group":"Components","description":"Hierarchical, expandable tree of items.","icon":"tree-view"},{"label":"useAureaStrings","href":"useaureastrings.html","group":"Hooks","description":"Read the string dictionary the provider is using, to translate your own labels with it.","icon":"gear"},{"label":"useAureaTheme","href":"useaureatheme.html","group":"Hooks","description":"Read theme and density straight from the document, and set them — for a host that owns the <html> attributes.","icon":"sun"},{"label":"useDensity","href":"usedensity.html","group":"Hooks","description":"Read the current density and switch it, from anywhere inside AureaProvider.","icon":"gear"},{"label":"useDeslize","href":"usedeslize.html","group":"Hooks","description":"Slides the selected item of SegmentedControl and Tabs from the previous position to the new one, copying its paint onto a passing indicator; instant under reduced motion.","icon":"arrow-right"},{"label":"usePortalContainer","href":"useportalcontainer.html","group":"Hooks","description":"The node every Aurea popup is mounted into, as configured once on AureaProvider.","icon":"gear"},{"label":"useReorder","href":"usereorder.html","group":"Hooks","description":"The accessible drag-and-drop reordering protocol, shared by SortableList and BlockEditor.","icon":"dots-six"},{"label":"useSidebar","href":"usesidebar.html","group":"Hooks","description":"The sidebar state — collapsed, setCollapsed, toggle — inside Sidebar.Provider or an AppShell with sidebarCollapsible.","icon":"sidebar-simple"},{"label":"useSpriteUrl","href":"usespriteurl.html","group":"Hooks","description":"Read where the provider is loading icon glyphs from.","icon":"image"},{"label":"useTheme","href":"usetheme.html","group":"Hooks","description":"Read the current theme and switch it, from anywhere inside AureaProvider.","icon":"sun"},{"label":"useToast","href":"usetoast.html","group":"Hooks","description":"Raise a transient notification from anywhere inside AureaProvider.","icon":"bell"},{"label":"useValorResponsivo","href":"usevalorresponsivo.html","group":"Hooks","description":"Resolves a Responsive<T> into the single value that applies right now — by viewport, by container, or not at all.","icon":"faders"},{"label":"Accordion · Questions on a marketing page","href":"pattern-accordion-questions-on-a-marketing-page.html","group":"Patterns","description":"The title is the question in the reader's own words, not a category. An accordion earns its place when the reader wants one answer, not all of them — otherwise plain headings read faster."},{"label":"Accordion · Advanced options, folded away","href":"pattern-accordion-advanced-options-folded-away.html","group":"Patterns","description":"The defaults are enough for most people, so the rest starts closed. Folding is not hiding: the summary line says what is inside, so nobody has to open it to find out."},{"label":"Alert · Inline notice","href":"pattern-alert-inline-notice.html","group":"Patterns","description":"Context that belongs to the section it sits in — an Alert stays put; a Toast would vanish."},{"label":"Alert · Failure with retry","href":"pattern-alert-failure-with-retry.html","group":"Patterns","description":"What broke, plus the way out in the same block. An error without an action is a dead end."},{"label":"Alert · Degraded service","href":"pattern-alert-degraded-service.html","group":"Patterns","description":"Page-width notice for something that affects the whole surface, dismissible by the reader."},{"label":"Alert · Nothing found","href":"pattern-alert-nothing-found.html","group":"Patterns","description":"The empty result of a filter: says why it is empty and offers the way back."},{"label":"Alert · Determinate upload","href":"pattern-alert-determinate-upload.html","group":"Patterns","description":"Known progress with a label. Unknown progress is a Skeleton or a spinner, never a fake bar."},{"label":"Alert · Loading placeholder","href":"pattern-alert-loading-placeholder.html","group":"Patterns","description":"The shape of the content before the content — Skeleton is aria-hidden by design."},{"label":"AppShell · The frame of a whole application","href":"pattern-appshell-the-frame-of-a-whole-application.html","group":"Patterns","description":"Brand and global actions on the topbar, the sections on the sidebar, the screen in the middle. It is the only component that owns page landmarks — one per document, never nested — and it emits the skip link for free, which is what closes WCAG 2.4.1 without the consumer writing anything."},{"label":"AppShell · A topbar joined to the page","href":"pattern-appshell-a-topbar-joined-to-the-page.html","group":"Patterns","description":"`topbarVariant=\"flush\"` drops the floating surface and welds the bar to the top edge. Pick one of the two per application and hold it: floating on one screen and flush on the next reads as two products, not as two screens."},{"label":"AppShell · The sidebar out of the way","href":"pattern-appshell-the-sidebar-out-of-the-way.html","group":"Patterns","description":"`sidebarCollapsed` is controlled by the consumer, like `open` on the palette: the shell never decides on its own that the navigation should disappear. The toggle in the brand slot is emitted by the shell and drives the same sidebar on small screens, where it opens as a popover instead of a column."},{"label":"AppShell · The sidebar from top to bottom","href":"pattern-appshell-the-sidebar-from-top-to-bottom.html","group":"Patterns","description":"`layout=\"sidebar\"` drops the bar that spans the window: the sidebar runs from the top to the bottom, the brand lives at its top and the person at its bottom, and only the list scrolls. The collapse button sits beside the page title (`AppShell.SidebarToggle`)."},{"label":"AppShell · A bar over the content alone","href":"pattern-appshell-a-bar-over-the-content-alone.html","group":"Patterns","description":"Pass `topbar` and the bar comes back over the content column only, with the collapse button first in it. What goes in `topbarActions` sits at its far end, away from the title — search, the theme switch, the account. The sidebar keeps running from top to bottom."},{"label":"AppShell · The sidebar that becomes a capsule","href":"pattern-appshell-the-sidebar-that-becomes-a-capsule.html","group":"Patterns","description":"`sidebarCollapsible=\"capsule\"`: collapsed, the floating sidebar keeps its rail of icons with the control radius — a capsule — instead of the card radius. The button at the seam collapses and expands it, and so does Ctrl+B (Cmd+B on a Mac)."},{"label":"AppShell · The sidebar that leaves the screen","href":"pattern-appshell-the-sidebar-that-leaves-the-screen.html","group":"Patterns","description":"`sidebarCollapsible=\"offcanvas\"`: collapsed, the sidebar leaves the screen and the content takes the whole width. The button beside the title brings it back. It is the reference's off-canvas mode."},{"label":"AppShell · The collapse button inside the sidebar","href":"pattern-appshell-the-collapse-button-inside-the-sidebar.html","group":"Patterns","description":"`sidebarToggle=\"none\"` keeps the shell from placing its own button, and the app puts `Sidebar.Toggle` where it wants — here, as the `action` of the brand at the top of the sidebar. Collapsed, the button moves under the logo."},{"label":"AppShell · Sections with the list beside them","href":"pattern-appshell-sections-with-the-list-beside-them.html","group":"Patterns","description":"`sidebarPanel=\"docked\"`: the first level of `navItems` becomes sections — a rail of icons — and the list of the chosen section sits in a panel beside it. Collapsing hides the panel and keeps the rail."},{"label":"AppShell · Sections with the list over the page","href":"pattern-appshell-sections-with-the-list-over-the-page.html","group":"Patterns","description":"`sidebarPanel=\"overlay\"`: the rail of sections stays narrow, and the list of a section opens over the page, next to its icon. Focus moves into the list, and Escape or a click outside closes it."},{"label":"AppShell · The current item of the sidebar, five ways","href":"pattern-appshell-the-current-item-of-the-sidebar-five-ways.html","group":"Patterns","description":"`sidebarIndicator` sets how the item you are on is drawn: `brand` (the default), `segment` (the capsule of the selected tab, with no line), `segment-dot`, `segment-line` and `subtle`. Switch them here, on the real shell."},{"label":"AspectRatio · A media slot that reserves its space","href":"pattern-aspectratio-a-media-slot-that-reserves-its-space.html","group":"Patterns","description":"The box holds the shape before the image arrives, so nothing below it jumps when it does. That is the whole job: not cropping the picture, but stopping the layout from shifting under the reader — the failure a card grid makes most visibly."},{"label":"AspectRatio · One ratio held across a grid","href":"pattern-aspectratio-one-ratio-held-across-a-grid.html","group":"Patterns","description":"Cards of different image heights read as a broken grid even when every card is correct. Fixing the ratio in one place is what makes the row line up, and it survives a source image nobody checked."},{"label":"AspectRatio · A square, for identity","href":"pattern-aspectratio-a-square-for-identity.html","group":"Patterns","description":"`ratio={1}` is the default because the square is the shape identity uses — an avatar, a logo, a QR code. Naming it explicitly in the code is still worth it: a reader who sees `ratio={1}` knows the square was chosen, not inherited."},{"label":"Avatar · Initials when there is no picture","href":"pattern-avatar-initials-when-there-is-no-picture.html","group":"Patterns","description":"The fallback is not a placeholder, it is the normal case: most people in most systems have no photo. Initials come from the name so two rows never look alike by accident."},{"label":"AvatarGroup · Who is on this run","href":"pattern-avatargroup-who-is-on-this-run.html","group":"Patterns","description":"Overlapping faces plus a count for the rest. The cutoff exists because a row of twelve avatars stops being information and becomes texture — the number carries what the faces no longer can."},{"label":"Badge · Version tag","href":"pattern-badge-version-tag.html","group":"Patterns","description":"Short metadata next to a title — the release the page documents."},{"label":"Badge · Maturity scale","href":"pattern-badge-maturity-scale.html","group":"Patterns","description":"The whole maturity ladder in one row, so a reader places an item at a glance."},{"label":"Badge · Count on a label","href":"pattern-badge-count-on-a-label.html","group":"Patterns","description":"A number that changes, kept quiet: neutral, so it never competes with a status."},{"label":"Badge · Badge next to Status","href":"pattern-badge-badge-next-to-status.html","group":"Patterns","description":"Badge classifies, Status reports a condition. Together they answer what and how."},{"label":"Badge · Categories, not statuses","href":"pattern-badge-categories-not-statuses.html","group":"Patterns","description":"Eight colour names mark a group — a section, a kind of item — and say nothing about health, so they never compete with success or danger. Yellow is left out: it belongs to the brand. The word and the icon carry the meaning; the colour only helps the eye find the group again."},{"label":"Badge · One category in three emphases","href":"pattern-badge-one-category-in-three-emphases.html","group":"Patterns","description":"The categories take the same three emphases as every other badge: soft for a list, solid for the one that must stand out, outline (since 0.34.0 a light tint, no line) when the surface is already busy."},{"label":"Banner · Something that affects the whole page","href":"pattern-banner-something-that-affects-the-whole-page.html","group":"Patterns","description":"A banner spans the region it is about; an alert sits inside it. Dismissible only when the message is genuinely optional — a banner about degraded service that can be closed is a banner nobody sees twice."},{"label":"Banner · The cookie notice","href":"pattern-banner-the-cookie-notice.html","group":"Patterns","description":"variant=\"consent\" asks before setting cookies that are not necessary: reject them, accept all, or choose by category in a window. Rejecting is as easy to see as accepting — same weight, same place —, the optional categories start off, and after the choice the confirmation takes the focus. Put the notice at the top of the page, before the skip link, and do not fix it to the screen. To change the choice later, show it again from a link in the footer, with value set to what you stored."},{"label":"Breadcrumb · Where this page sits","href":"pattern-breadcrumb-where-this-page-sits.html","group":"Patterns","description":"Every level is a link except the last, which is the page itself and carries aria-current. A breadcrumb whose last item is also a link tells the screen reader that the user can navigate to where they already are."},{"label":"Button · With leading icon","href":"pattern-button-with-leading-icon.html","group":"Patterns","description":"The main action of a screen, with the glyph repeating the verb — never replacing it."},{"label":"Button · Submitting","href":"pattern-button-submitting.html","group":"Patterns","description":"Busy state for a form submit: spinner, aria-busy and the label kept for context."},{"label":"Button · Confirm and cancel","href":"pattern-button-confirm-and-cancel.html","group":"Patterns","description":"The pair that closes a dialog: one primary, one ghost. Cancel is never a button of equal weight."},{"label":"Button · With text","href":"pattern-button-with-text.html","group":"Patterns","description":"Secondary action that still needs an edge — a neutral choice next to a primary one."},{"label":"Button · With trailing chevron","href":"pattern-button-with-trailing-chevron.html","group":"Patterns","description":"Opens a menu or a list. The chevron announces that something unfolds."},{"label":"Button · Destructive with icon","href":"pattern-button-destructive-with-icon.html","group":"Patterns","description":"Irreversible action. The red plus the glyph make the consequence readable before the click."},{"label":"Button · Toolbar trio","href":"pattern-button-toolbar-trio.html","group":"Patterns","description":"Three low-emphasis actions side by side, where the surface below must keep reading."},{"label":"Button · Icon only","href":"pattern-button-icon-only.html","group":"Patterns","description":"Square target with an accessible name — an icon without a label needs one."},{"label":"Button · Segmented range","href":"pattern-button-segmented-range.html","group":"Patterns","description":"Coordinated set of the same control. Each button stays tabbable — that is what separates it from a Toolbar."},{"label":"Button · With Kbd","href":"pattern-button-with-kbd.html","group":"Patterns","description":"The action and the key that fires it, together — shown and announced by aria-keyshortcuts."},{"label":"Button · Destructive with Kbd","href":"pattern-button-destructive-with-kbd.html","group":"Patterns","description":"Irreversible plus a shortcut: the key is spelled out so nobody discovers it by accident."},{"label":"Button · Inline action","href":"pattern-button-inline-action.html","group":"Patterns","description":"Inside a sentence, where a capsule would break the line: text, underlined at rest."},{"label":"Button · Pinned filter","href":"pattern-button-pinned-filter.html","group":"Patterns","description":"A filter that stays on: aria-pressed keeps the state visible and audible after the click."},{"label":"Button · Full width on a narrow screen","href":"pattern-button-full-width-on-a-narrow-screen.html","group":"Patterns","description":"Form footer on a phone: the action takes the whole width so the thumb cannot miss it."},{"label":"Button · With counter","href":"pattern-button-with-counter.html","group":"Patterns","description":"Action carrying a live number: the Badge rides inside the label, not beside it."},{"label":"Button · The two axes","href":"pattern-button-the-two-axes.html","group":"Patterns","description":"Appearance is how much weight the box has; tone is what the colour means. The old names are shortcuts for pairs — variant=\"danger-outline\" and appearance/tone below render the same button."},{"label":"Button · Confirming a safe outcome","href":"pattern-button-confirming-a-safe-outcome.html","group":"Patterns","description":"Success tone for an action that lands somewhere good — publishing, approving, marking done. Filled, because tone and weight are independent: choosing green does not force the button to be quieter."},{"label":"Button · Warning is not the brand","href":"pattern-button-warning-is-not-the-brand.html","group":"Patterns","description":"Amber, not the Aurea yellow. Until August 2026 the warning token resolved to the brand colour in dark theme — same pixels, two different meanings — so warning was not a tone at all. It has its own identity now, picked by measuring perceptual distance from both neighbours: the brand on one side, the destructive red on the other."},{"label":"Button · Informational action in running text","href":"pattern-button-informational-action-in-running-text.html","group":"Patterns","description":"Info tone on the link appearance: a pointer to context that is neither a warning nor a commitment."},{"label":"Button · The same tone across appearances","href":"pattern-button-the-same-tone-across-appearances.html","group":"Patterns","description":"One tone, four weights — and every cell exists. A tone never loses its filled form: each one owns a colour and the text colour that goes on top of it, chosen per theme and verified for AA contrast, exactly as the destructive tone always had."},{"label":"Button · Stacked actions","href":"pattern-button-stacked-actions.html","group":"Patterns","description":"A vertical group for a menu of actions on a card or in a side panel. The buttons all measure the same width — without that the column comes out ragged, which is the one defect a vertical group cannot have. It stays role=\"group\" and announces no orientation: it does not navigate by arrow, and promising keyboard that does not exist is worse than staying quiet."},{"label":"Button · The same button in three container widths","href":"pattern-button-the-same-button-in-three-container-widths.html","group":"Patterns","description":"One button, one value, one viewport — three container widths. The step comes from the space the component was placed in, not from the size of the window, so a sidebar and a main column can show the same component at different steps at the same time. This is the proof that separates the two mechanisms: if the three measured the same, what existed would be a media query under another name. The parent needs `container-scope`, which names the container — an unnamed one matches the nearest ancestor that happens to be a container, including one somebody else declared for another reason."},{"label":"Button · Reacting to the window instead","href":"pattern-button-reacting-to-the-window-instead.html","group":"Patterns","description":"The other mechanism, for when the decision really does belong to the application and not to the slot: the step follows the viewport. Same axis, same scale, and the prefix in the emitted class says which of the two is measuring — `md` is always 768px, and never means two things depending on where you read it. Resize the window to see it move; the example above will not move, because its containers have fixed widths."},{"label":"Button · Every family follows its own scale","href":"pattern-button-every-family-follows-its-own-scale.html","group":"Patterns","description":"The same three containers, now with one piece from each family. Control, mark and avatar come from the control height and step together; the icon inside the button comes from the glyph scale and does NOT follow the button — a large button with a huge glyph is not a larger button, it is a different drawing. The two behaviours in one picture are the point: sharing a step is measured, never assumed."},{"label":"ButtonGroup · Time range","href":"pattern-buttongroup-time-range.html","group":"Patterns","description":"Day, week, month over the same chart — the label names the set, the buttons the spans."},{"label":"ButtonGroup · Pinned filters","href":"pattern-buttongroup-pinned-filters.html","group":"Patterns","description":"Many-of-many: each button is its own toggle, so two can be on at once."},{"label":"ButtonGroup · View switch","href":"pattern-buttongroup-view-switch.html","group":"Patterns","description":"One-of-many is not this component: SegmentedControl carries one value and one tab stop."},{"label":"ButtonGroup · Share actions","href":"pattern-buttongroup-share-actions.html","group":"Patterns","description":"Glyph-only set at the end of a card: one name for the group, one for each action."},{"label":"Calendar · Date picker","href":"pattern-calendar-date-picker.html","group":"Patterns","description":"There is no DatePicker component: a picker is a trigger plus a popover plus this calendar. Three parts you already have, and the trigger is what names the field."},{"label":"Calendar · Booking with days closed","href":"pattern-calendar-booking-with-days-closed.html","group":"Patterns","description":"The reason this component exists. A native date input cannot say \"not before Thursday, and never a Sunday\" — everything else about a plain date, it does better."},{"label":"Calendar · When the native input wins","href":"pattern-calendar-when-the-native-input-wins.html","group":"Patterns","description":"One plain date, no closed days: the native picker is smaller, knows every locale, and is the one the person already knows how to use on their phone."},{"label":"Card · Titled surface","href":"pattern-card-titled-surface.html","group":"Patterns","description":"The plain floating surface: title, one line of context, radius 22."},{"label":"Card · Header with action","href":"pattern-card-header-with-action.html","group":"Patterns","description":"Title on the left, the action on the right, on the same baseline. The card owns its own header."},{"label":"Card · Selectable tile","href":"pattern-card-selectable-tile.html","group":"Patterns","description":"A card that is a target. The interactive variant carries the hover and the focus ring — and it requires `render`, because only the caller knows whether the tile is an action (<button>) or a link (<a href>)."},{"label":"Card · KPI row","href":"pattern-card-kpi-row.html","group":"Patterns","description":"Three numbers of the same weight. One line, equal columns, trend beside the value."},{"label":"Card · Member row","href":"pattern-card-member-row.html","group":"Patterns","description":"Avatar, name and role — the identity line that repeats in every list of people."},{"label":"Card · Facts list","href":"pattern-card-facts-list.html","group":"Patterns","description":"Term and value in two columns — for a record's attributes, not for tabular data."},{"label":"Card · Activity timeline","href":"pattern-card-activity-timeline.html","group":"Patterns","description":"What happened, in order, with the time on the side. History, not a feed of live events."},{"label":"Card · A summary at the top of an article","href":"pattern-card-a-summary-at-the-top-of-an-article.html","group":"Patterns","description":"Three short points before the long text, for the reader who has thirty seconds. It is a card with a short title and a list, not an alert: an alert interrupts, a summary waits to be read. The check icon is decoration; the list is announced as a list."},{"label":"Card · The card that stands out","href":"pattern-card-the-card-that-stands-out.html","group":"Patterns","description":"The main card of a screen. In the light theme it is the dark theme's card; in the dark theme, the regular card (the yellow outline went with the lines in 0.34.0). Inside it the whole dark theme applies, so text, badges and buttons adjust by themselves. Not for a list of choices: in the dark theme its outline is close to `selected`."},{"label":"Card · A colour stroke on top","href":"pattern-card-a-colour-stroke-on-top.html","group":"Patterns","description":"A stroke on the top edge in the tone's fill colour, the same in both themes. It is decoration: the title already says the subject."},{"label":"Chart · One series over time","href":"pattern-chart-one-series-over-time.html","group":"Patterns","description":"Chart is the frame, not the drawing: it carries the accessible name, the sizing and the surface, and the series comes in as a child of the chart library. That split is what lets the drawing engine be swapped without touching the page."},{"label":"Chart · Two series, read together","href":"pattern-chart-two-series-read-together.html","group":"Patterns","description":"Two bars side by side answer a question one bar cannot: not how many runs, but how many of them failed. The legend is required here — with two series the colours stop being decoration and start carrying meaning."},{"label":"Chart · The whole reading surface","href":"pattern-chart-the-whole-reading-surface.html","group":"Patterns","description":"Grid, axis, legend and tooltip on one chart — the assembled form, so the pieces are seen doing their jobs together instead of one at a time. `defaultIndex` pins the tooltip because a static page has no pointer; in an application it is not needed."},{"label":"ChartLegend · Naming the colours of a stacked series","href":"pattern-chartlegend-naming-the-colours-of-a-stacked-series.html","group":"Patterns","description":"Stacking hides which band is which, so the legend stops being optional: it is the only place the reader learns that the darker band is the failures. It sits under the drawing by default, where it does not compete with the axis for the first read."},{"label":"ChartLegend · Legend above the drawing","href":"pattern-chartlegend-legend-above-the-drawing.html","group":"Patterns","description":"`verticalAlign=\"top\"` reads the names before the shapes, which is what a dashboard tile wants when the drawing is short and the reader is scanning several tiles at once. Everything else stays: the component still takes the series from the engine, never a hand-written list."},{"label":"ChartTooltip · The exact value under the pointer","href":"pattern-charttooltip-the-exact-value-under-the-pointer.html","group":"Patterns","description":"An area chart shows a shape, not a number; the tooltip is where the number lives. It reuses the same `.tooltip` surface as the rest of the system, so a value read on a chart looks like a value read anywhere else."},{"label":"ChartTooltip · Every series at one point in time","href":"pattern-charttooltip-every-series-at-one-point-in-time.html","group":"Patterns","description":"With more than one series the tooltip becomes a small table: the label is the point on the axis, and each row is a series with its colour swatch. This is the comparison the drawing cannot make, because two bars of different heights do not tell you their difference."},{"label":"Checkbox · One box that gates the action","href":"pattern-checkbox-one-box-that-gates-the-action.html","group":"Patterns","description":"The label is the whole sentence and it is clickable — a checkbox whose label is not part of the target is a 16px hit area, which fails on touch. Never pre-checked when it grants permission."},{"label":"Checkbox · A set where several answers are right","href":"pattern-checkbox-a-set-where-several-answers-are-right.html","group":"Patterns","description":"Checkbox, not radio, is the difference between 'pick any' and 'pick one'. The rule is the answer, not the look: if zero selected is a legitimate state, it is a checkbox."},{"label":"Cluster · A row of actions that wraps instead of overflowing","href":"pattern-cluster-a-row-of-actions-that-wraps-instead-of-overflowing.html","group":"Patterns","description":"Buttons side by side with the gap of the system, and a wrap that happens before anything is pushed off screen. Writing `display:flex` by hand gets the row right and the wrap wrong, which is only visible on the narrow viewport nobody tested."},{"label":"Cluster · Tags under a heading","href":"pattern-cluster-tags-under-a-heading.html","group":"Patterns","description":"A cluster of badges is the shape a filter list and a tag list share. The primitive is what keeps the vertical rhythm right when the second row appears — the case a hand-written flex row almost always gets wrong."},{"label":"Cluster · Metadata beside a title","href":"pattern-cluster-metadata-beside-a-title.html","group":"Patterns","description":"Title, status and time on one line, aligned on their centres rather than their boxes. The alignment is the point: three elements of different heights on a hand-written row sit on three different baselines."},{"label":"CodeBlock · The install line","href":"pattern-codeblock-the-install-line.html","group":"Patterns","description":"The shortest useful block: one command, one button. `copyable` is what makes it a block instead of a paragraph — a reader who has to select the text by hand will select the prompt with it."},{"label":"CodeBlock · A snippet under a heading","href":"pattern-codeblock-a-snippet-under-a-heading.html","group":"Patterns","description":"The shape every documentation page repeats: a sentence that says what the code does, then the code. The block keeps its own horizontal scroll, so a long line never widens the page around it."},{"label":"CodeBlock · Output, not source","href":"pattern-codeblock-output-not-source.html","group":"Patterns","description":"`language=\"text\"` is the default for a reason: not everything in a block is code. A stack trace or a command's output is quoted verbatim, and pretending it is a language would colour tokens that are not tokens."},{"label":"CodeEditor · A snippet the reader can change","href":"pattern-codeeditor-a-snippet-the-reader-can-change.html","group":"Patterns","description":"An editor, not a code block: the reader types. Use it where the change is the point — a query, a config, a rule — and use CodeBlock everywhere else, because a read-only editor costs a bundle it does not earn."},{"label":"Collapsible · Advanced options, folded away","href":"pattern-collapsible-advanced-options-folded-away.html","group":"Patterns","description":"The default answer for a form section most people never open. `defaultOpen` is left off and the state stays inside the component — a consumer that does not need to read the state should not have to hold it."},{"label":"Collapsible · A detail already unfolded","href":"pattern-collapsible-a-detail-already-unfolded.html","group":"Patterns","description":"`defaultOpen` starts unfolded but leaves the reader in charge of folding it back. Use it when the content is the point of the screen and the fold is a courtesy, not a filter."},{"label":"Collapsible · Fold driven from outside","href":"pattern-collapsible-fold-driven-from-outside.html","group":"Patterns","description":"`open` plus `onOpenChange` when something else in the screen decides — a \"expand all\" button, a deep link, a search that has to reveal the match it found. Passing `open` without `onOpenChange` freezes it, which is a legitimate read-only state and not a bug."},{"label":"Collapsible · A section that cannot be opened yet","href":"pattern-collapsible-a-section-that-cannot-be-opened-yet.html","group":"Patterns","description":"`disabled` keeps the row in place while the content is unavailable, instead of removing it. A section that disappears and comes back renumbers everything around it; a section that stays says the same thing without moving anything."},{"label":"Combobox · Picking one out of many","href":"pattern-combobox-picking-one-out-of-many.html","group":"Patterns","description":"A select stops working somewhere around twenty options — the eye cannot scan them. A combobox lets the user type what they already know instead of hunting for it."},{"label":"Combobox · Options that belong to sections","href":"pattern-combobox-options-that-belong-to-sections.html","group":"Patterns","description":"A flat list of forty time zones is a wall; the same forty under continents is a map. Pass groups — `{label, items}` — in the same `items` prop, and the engine's filter runs inside each section, dropping a section that has nothing left to show. `empty` writes what appears when nothing matches, which is where a list stops saying No results and starts saying what the user can do about it."},{"label":"CommandPaletteShell · Every command on one keystroke","href":"pattern-commandpaletteshell-every-command-on-one-keystroke.html","group":"Patterns","description":"The palette is the keyboard route to anything the application can do. The field takes focus on open and the list narrows as you type, so the whole interaction is one gesture — never a menu you have to find first."},{"label":"CommandPaletteShell · Results narrowed by what was typed","href":"pattern-commandpaletteshell-results-narrowed-by-what-was-typed.html","group":"Patterns","description":"Filtering is the consumer's job, not the shell's: it holds `query` and decides what matches. Keeping it outside is what lets the same palette search components, files or an API — the shell never assumes the shape of what it is searching."},{"label":"CommandPaletteShell · Nothing matched","href":"pattern-commandpaletteshell-nothing-matched.html","group":"Patterns","description":"The one state a palette must not skip. A list that simply vanishes reads as a broken palette; EmptyState says the search ran and found nothing, which is a different fact and the one the reader needs."},{"label":"ContextMenu · Right-click on an item","href":"pattern-contextmenu-right-click-on-an-item.html","group":"Patterns","description":"The menu the mouse expects on an item, and the keyboard reaches with Shift+F10. It never replaces a visible control: everything here has another way in."},{"label":"DataGrid · A list you act on in bulk","href":"pattern-datagrid-a-list-you-act-on-in-bulk.html","group":"Patterns","description":"Selection turns a table into a work surface: pick the rows, then act once. The header checkbox selects the page, never the whole dataset — a promise a static table cannot keep."},{"label":"DataList · The facts about one record","href":"pattern-datalist-the-facts-about-one-record.html","group":"Patterns","description":"A definition list is the honest markup for \"this thing has these properties\". Every value here belongs to the same run; nothing on the list compares it to another run."},{"label":"DataList · Values that are components","href":"pattern-datalist-values-that-are-components.html","group":"Patterns","description":"`value` takes any node, so a status reads as a status and an identity reads as an identity. The alternative — spelling \"Succeeded\" as text — loses the one thing the reader scans for when the list is long."},{"label":"DataList · Inside a card, under a heading","href":"pattern-datalist-inside-a-card-under-a-heading.html","group":"Patterns","description":"The shape a detail panel repeats: a title that names the record and the list that describes it. The card supplies the surface; the list supplies the structure — neither tries to do the other's job."},{"label":"DataList · A spec sheet in groups","href":"pattern-datalist-a-spec-sheet-in-groups.html","group":"Patterns","description":"A long list of facts reads better cut by subject. Each group is a card with its own title and its own list; the grid lays the cards side by side and stacks them on a phone. No group component to learn — the parts already exist."},{"label":"DependencyGraph · A network map, top to bottom","href":"pattern-dependencygraph-a-network-map-top-to-bottom.html","group":"Patterns","description":"The internet on top and each layer below. The kind of device is a word with an icon beside it; badges carry the count and the status; ports name the ends of the lines; the line's drawing says what kind of link it is without colour — double for fibre — and its state comes apart, as a colour, a word and a cross when down. The legend builds itself in two parts: the kind of link and the state. Repeated links between the same two devices collapse into one with their count."},{"label":"DependencyGraph · The legend and the overview step aside","href":"pattern-dependencygraph-the-legend-and-the-overview-step-aside.html","group":"Patterns","description":"On a large map the legend and the overview cover the devices in the bottom corners. With legendCollapsible the legend gets a Legend button that stays in its corner: open, the list rises above it; closed, only the button is left. With minimapToggle the overview gets a button beside the zoom buttons, at the top. Both start open; defaultLegendOpen and defaultMinimapOpen start them closed."},{"label":"Dialog · Destructive confirmation","href":"pattern-dialog-destructive-confirmation.html","group":"Patterns","description":"The pause before something irreversible. The title asks the question, the body says what is lost, and the confirming button carries the danger tone — never the cancel."},{"label":"Dialog · Short form in a dialog","href":"pattern-dialog-short-form-in-a-dialog.html","group":"Patterns","description":"A dialog is the right home for a form only when it is short enough to fit without scrolling. The primary action repeats the verb of the title, so the user never has to re-read what they are confirming."},{"label":"Drawer · Detail panel beside the list","href":"pattern-drawer-detail-panel-beside-the-list.html","group":"Patterns","description":"The row stays on screen and the detail slides in beside it — the reason to pick a drawer over a dialog is exactly this: the context does not disappear."},{"label":"Drawer · Filters that stay open while you read","href":"pattern-drawer-filters-that-stay-open-while-you-read.html","group":"Patterns","description":"Filters on the left, results on the right. A dialog would cover the results the filters are changing, which is the one thing a filter panel must not do."},{"label":"DropdownMenu · The overflow menu of a table row","href":"pattern-dropdownmenu-the-overflow-menu-of-a-table-row.html","group":"Patterns","description":"Three dots at the end of the row. Destructive items sit last, after a separator, so the pointer never lands on Delete while reaching for Rename."},{"label":"DropdownMenu · A primary action with variants behind it","href":"pattern-dropdownmenu-a-primary-action-with-variants-behind-it.html","group":"Patterns","description":"The button does the common thing; the chevron opens the rest. The label of the button is the action itself, never the word More."},{"label":"DropdownMenu · A menu that holds STATE, not just commands","href":"pattern-dropdownmenu-a-menu-that-holds-state-not-just-commands.html","group":"Patterns","description":"The View menu of any application: things that toggle, things that are mutually exclusive, and a section label that names the group instead of pretending to be an item. Until 28/08/2026 the Aurea menu could express none of these — `items` had a single shape, and the engine underneath had five (G-API-02)."},{"label":"EmptyState · Nothing here yet, and one way forward","href":"pattern-emptystate-nothing-here-yet-and-one-way-forward.html","group":"Patterns","description":"The empty state of a new account is not an error: it says what will appear and offers the one action that fills it. Never the same copy as a search with no results — those are different situations wearing the same layout."},{"label":"EmptyState · The filter matched nothing","href":"pattern-emptystate-the-filter-matched-nothing.html","group":"Patterns","description":"Different from an empty account: here there IS data, the query just missed it. The action clears the filter instead of creating something — offering Create here sends people down the wrong path."},{"label":"Field · Email field","href":"pattern-field-email-field.html","group":"Patterns","description":"Label, control and hint bound together — the hint is read by the screen reader, not painted beside it."},{"label":"Field · Rejected value","href":"pattern-field-rejected-value.html","group":"Patterns","description":"The error joins the accessible description and marks the control invalid. A red field alone tells a colour-blind user nothing."},{"label":"Field · Plan picker","href":"pattern-field-plan-picker.html","group":"Patterns","description":"One value out of a known set. Select chooses a value; a Menu would execute an action."},{"label":"Field · Settings block","href":"pattern-field-settings-block.html","group":"Patterns","description":"A short settings form: text, long text and two toggles, in one column with a single primary action."},{"label":"Field · Filter row","href":"pattern-field-filter-row.html","group":"Patterns","description":"Search plus a scope select — the pair that heads most collections."},{"label":"FileInput · Dropping files with a limit","href":"pattern-fileinput-dropping-files-with-a-limit.html","group":"Patterns","description":"The limits are written before the mistake, not after it: type and size are on the field, so the refusal never surprises. Dropping and clicking reach the same input, because a drop zone that is not also a button is unusable by keyboard."},{"label":"Header · The bar that carries the brand and the global actions","href":"pattern-header-the-bar-that-carries-the-brand-and-the-global-actions.html","group":"Patterns","description":"Brand on the left, actions on the right, and nothing in between that belongs to a single page. The floating variant sits on the content; flush joins the page — pick one per application, not per screen."},{"label":"Header · A website header, with the current page marked","href":"pattern-header-a-website-header-with-the-current-page-marked.html","group":"Patterns","description":"The same list the Sidebar and the BottomNav take goes in items, and current marks the page you are on. Below 768px the links leave the bar and drop into the menu panel; the actions stay in the bar. maxWidth lines the bar up with the Container of the page."},{"label":"HoverCard · Who this person is, without leaving the sentence","href":"pattern-hovercard-who-this-person-is-without-leaving-the-sentence.html","group":"Patterns","description":"A name in running text is an identifier, not an identity. The card answers \"who?\" in place, and the profile page it previews stays one click away — the preview is a shortcut, never the only route."},{"label":"HoverCard · Previewing what a link leads to","href":"pattern-hovercard-previewing-what-a-link-leads-to.html","group":"Patterns","description":"`side=\"top\"` when the trigger sits low in the viewport and a card below it would be cut off. The rest is unchanged: the preview saves a navigation, it does not replace one."},{"label":"IconButton · Row actions","href":"pattern-iconbutton-row-actions.html","group":"Patterns","description":"The trio at the end of a table row: open, edit, delete — quiet until the row matters."},{"label":"IconButton · Card header action","href":"pattern-iconbutton-card-header-action.html","group":"Patterns","description":"One glyph in the corner of a surface: the title keeps the space, the action keeps the reach."},{"label":"IconButton · Starred row","href":"pattern-iconbutton-starred-row.html","group":"Patterns","description":"State that survives the click: aria-pressed keeps it visible and audible."},{"label":"IconButton · Canvas controls","href":"pattern-iconbutton-canvas-controls.html","group":"Patterns","description":"Zoom and fit in a toolbar: one tab stop for the set, a name for each glyph."},{"label":"IconButton · Dismiss a banner","href":"pattern-iconbutton-dismiss-a-banner.html","group":"Patterns","description":"The close of a notice: destructive ghost, so removing is available without being the point."},{"label":"Input · Email and password","href":"pattern-input-email-and-password.html","group":"Patterns","description":"The sign-in pair, with the autoComplete tokens the browser actually looks for."},{"label":"Input · Quantity with bounds","href":"pattern-input-quantity-with-bounds.html","group":"Patterns","description":"A number the browser keeps inside its range, with the limit written next to it."},{"label":"Input · Native date range","href":"pattern-input-native-date-range.html","group":"Patterns","description":"For one plain date the native picker still wins: every locale and every screen reader for free, and it is the one people already know. Reach for Calendar when you need a visible grid, a range, or days closed."},{"label":"Input · Generated identifier","href":"pattern-input-generated-identifier.html","group":"Patterns","description":"A value to copy, not to edit: read-only is still reachable by the keyboard, unlike disabled."},{"label":"Input · Account settings card","href":"pattern-input-account-settings-card.html","group":"Patterns","description":"A short form on a surface: text, a choice, two toggles and one primary action."},{"label":"Input · Settings row","href":"pattern-input-settings-row.html","group":"Patterns","description":"Label on the left, control on the right — the line every settings screen is made of. Until August 2026 this only came out of Aurea with ad-hoc CSS. It is a grid and not a row for one reason: in a row the error message would become a third column beside the control, and the error is about the value, so it belongs under it."},{"label":"Input · Composer with a toolbar below","href":"pattern-input-composer-with-a-toolbar-below.html","group":"Patterns","description":"One box, text on top and controls underneath. The addon takes a whole line instead of sitting beside the field, and the frame drops the pill radius for the panel radius — a group with a block addon is no longer a line, it is a surface. Measured: at 999px on a tall box the sides become half-circles and the field text collides with the curve."},{"label":"InputGroup · A unit that belongs to the value","href":"pattern-inputgroup-a-unit-that-belongs-to-the-value.html","group":"Patterns","description":"The suffix is not a label and not a hint: it is part of reading the number. Putting \"ms\" inside the group keeps it welded to the field at every width, where a paragraph beside it would wrap away on a phone."},{"label":"InputGroup · A prefix that cannot be typed away","href":"pattern-inputgroup-a-prefix-that-cannot-be-typed-away.html","group":"Patterns","description":"The scheme and host are fixed; only the path is the user's. Showing them as an addon instead of pre-filling the field means the reader can never delete them by holding backspace, and the value you read back is only ever the part you asked for."},{"label":"InputGroup · Both ends at once","href":"pattern-inputgroup-both-ends-at-once.html","group":"Patterns","description":"A currency on one side and a unit on the other, with the field between them. Two addons is the ceiling: a third leaves less room for the value than for the frame around it."},{"label":"InputGroup · A toolbar over the field","href":"pattern-inputgroup-a-toolbar-over-the-field.html","group":"Patterns","description":"`block-start` takes the whole line above the control, which is the only place a row of actions fits without stealing width from the value. This is the shape a composer wants: the field is the work, the bar is what you do to it."},{"label":"InputGroup · A counter under the field","href":"pattern-inputgroup-a-counter-under-the-field.html","group":"Patterns","description":"`block-end` for what the reader consults while typing, not before. The count belongs to the control, so it travels with it — unlike a hint on the Field, which describes the input before anyone has touched it."},{"label":"KPI · A number with its comparison","href":"pattern-kpi-a-number-with-its-comparison.html","group":"Patterns","description":"The delta only means something next to a period, so the trend line carries both. A KPI without a comparison is a number on a wall — true, and useless for deciding anything."},{"label":"KPI · The direction, not just the sign","href":"pattern-kpi-the-direction-not-just-the-sign.html","group":"Patterns","description":"`trend` takes a node, so the comparison can carry a status of its own. Colour alone would fail WCAG 1.4.1 — the arrow and the words are what make the direction readable without it."},{"label":"KPI · A row of tiles across the top of a dashboard","href":"pattern-kpi-a-row-of-tiles-across-the-top-of-a-dashboard.html","group":"Patterns","description":"Three or four side by side is the shape a dashboard opens with: the numbers that decide whether to keep reading. Past four they stop being a summary and become a table that forgot it was one."},{"label":"KPI · A trend with a direction","href":"pattern-kpi-a-trend-with-a-direction.html","group":"Patterns","description":"`direction` draws the arrow, colours the trend and gives screen readers a word before it — up is success and down is danger by default. When going up is bad news, `tone` turns it around. The trend text stays the domain's own words."},{"label":"KPI · Numbers inside a card that already exists","href":"pattern-kpi-numbers-inside-a-card-that-already-exists.html","group":"Patterns","description":"A KPI is a card, so three of them inside a panel would be boxes inside a box. `variant=\"plain\"` drops the card and keeps the column: the panel is the surface, and the numbers sit on it."},{"label":"Kbd · A shortcut inside a sentence","href":"pattern-kbd-a-shortcut-inside-a-sentence.html","group":"Patterns","description":"Prose is where the keyboard is taught. Marking the keys instead of quoting them means a screen reader announces them as keys, and the reader can tell `Esc` the key from \"esc\" the word."},{"label":"Kbd · One key per element in a chord","href":"pattern-kbd-one-key-per-element-in-a-chord.html","group":"Patterns","description":"`⌘ ⇧ P` is three elements, not one string. Split like this the keys line up with the physical keys the reader is looking for, and a chord never renders as a single wide pill that reads like one impossible key."},{"label":"Kbd · The shortcut column of a menu","href":"pattern-kbd-the-shortcut-column-of-a-menu.html","group":"Patterns","description":"A menu that lists its shortcuts teaches the keyboard without a separate page. The keys sit at the end of the row so the labels stay left-aligned and scannable — the shortcut is the second read, never the first."},{"label":"Kbd · On the button that performs it","href":"pattern-kbd-on-the-button-that-performs-it.html","group":"Patterns","description":"The one case where the keys must NOT be a bare Kbd: `kbd` on the Button both draws the shortcut and emits `aria-keyshortcuts`, so the shortcut is announced and not only seen. A Kbd dropped inside a button would be the decoration without the promise."},{"label":"LogStream · The tail of a running job","href":"pattern-logstream-the-tail-of-a-running-job.html","group":"Patterns","description":"Time, level and message in three fixed tracks, so the eye can find the level column without reading the lines. It is a live region: a line that arrives while the reader is elsewhere is announced, not silently appended."},{"label":"LogStream · Lines with no level of their own","href":"pattern-logstream-lines-with-no-level-of-their-own.html","group":"Patterns","description":"Program output is not levelled, and forcing a level on it would be inventing information. The three cells stay in place even when two are empty — that is what keeps the message in its own track instead of sliding left."},{"label":"LogStream · The log under the thing it describes","href":"pattern-logstream-the-log-under-the-thing-it-describes.html","group":"Patterns","description":"A log beside a status is the shape an operations panel repeats: the badge says what happened, the stream says why. Neither answers the other's question, which is why both are here."},{"label":"MediaPlayer · A clip with its title on the frame","href":"pattern-mediaplayer-a-clip-with-its-title-on-the-frame.html","group":"Patterns","description":"Title and subtitle ride on the player instead of above it, so the frame is self-contained wherever it is embedded. Every control is reachable by keyboard and announced from the string dictionary, which is what makes the player translatable."},{"label":"MediaPlayer · An episode, without the video frame","href":"pattern-mediaplayer-an-episode-without-the-video-frame.html","group":"Patterns","description":"The same player with kind=\"audio\": no picture area, the controls carry the whole component. Reaching for a second component here would double the keyboard surface for no gain."},{"label":"MediaPlayerShell · A stream with its own controls","href":"pattern-mediaplayershell-a-stream-with-its-own-controls.html","group":"Patterns","description":"The frame gives the surface, the aspect ratio and the dark canvas that holds in both themes; everything inside is yours. This is the shape to reach for when the engine is not a <video> — a remote screen, a canvas, a live socket."},{"label":"MediaPlayerShell · Waiting for a source","href":"pattern-mediaplayershell-waiting-for-a-source.html","group":"Patterns","description":"The state a player spends more time in than anyone plans for. Saying nothing reads as broken; the frame with a placeholder says the surface is ready and the source is not, which is the fact the reader needs while they wait."},{"label":"MediaPlayerShell · The source failed","href":"pattern-mediaplayershell-the-source-failed.html","group":"Patterns","description":"A dead stream is not an empty one: it needs the reason and a way out. Keeping the failure inside the frame instead of replacing the frame with an alert holds the layout still — the page does not jump when a tile drops."},{"label":"Menubar · The menu row of an editor","href":"pattern-menubar-the-menu-row-of-an-editor.html","group":"Patterns","description":"One row, and the arrow keys walk from an open menu straight into the next — that is what separates a menubar from three dropdowns side by side. It belongs to applications, not to websites."},{"label":"Menubar · The menu bar as a column","href":"pattern-menubar-the-menu-bar-as-a-column.html","group":"Patterns","description":"`orientation=\"vertical\"` stacks the bar and the menus open to the side — down would put them on top of the next item of the bar itself. The side is logical (`inline-end`), so in Arabic the column sits on the right and the menus open left without anyone writing a second rule."},{"label":"MessageComposer · The line you type into","href":"pattern-messagecomposer-the-line-you-type-into.html","group":"Patterns","description":"One field and one send. The icon is optional and the field does not reserve space for one that is not there — a defect this component actually shipped with, and the reason the InputGroup exists."},{"label":"MessageComposer · Disabled while the answer is being written","href":"pattern-messagecomposer-disabled-while-the-answer-is-being-written.html","group":"Patterns","description":"Sending twice is the mistake to prevent. Disabling the composer says the turn is not yours yet, which is clearer than a spinner somewhere else on the screen."},{"label":"MessageList · A thread between a person and an agent","href":"pattern-messagelist-a-thread-between-a-person-and-an-agent.html","group":"Patterns","description":"Author, time and body, with the delivery state on the message that has one. The list is a log: it does not reorder, and a failed message stays where it was written so the retry lands in context."},{"label":"MultiCombobox · Labelling something with several tags","href":"pattern-multicombobox-labelling-something-with-several-tags.html","group":"Patterns","description":"Each choice stays visible as a chip, so the user reads the whole selection without opening the list again. Backspace removes the last one — the keyboard shape people already expect from an email To: field."},{"label":"NotificationCenter · The bell in the top bar","href":"pattern-notificationcenter-the-bell-in-the-top-bar.html","group":"Patterns","description":"Grouped by day, unread first, and one control that clears the badge without opening every item. The count on the trigger is the only thing most people ever read."},{"label":"NumberField · A quantity with a floor and a ceiling","href":"pattern-numberfield-a-quantity-with-a-floor-and-a-ceiling.html","group":"Patterns","description":"The steppers are for small corrections and the keyboard is for big ones — both hit the same bounds. Bounds on the field, not in a message after submit: the refusal should never be a surprise."},{"label":"NumberField · A wide range you drag instead of clicking forty times","href":"pattern-numberfield-a-wide-range-you-drag-instead-of-clicking-forty-times.html","group":"Patterns","description":"Opacity 0–100, a width in pixels: ranges where the steppers are the wrong instrument. `scrubbable` adds a handle that changes the value as you pull it — the gesture every drawing tool has in a numeric field. It is opt-in and strictly additive: the buttons, the arrow keys and Home/End are untouched, and the handle is hidden from assistive technology because dragging is a pointer gesture with no keyboard equivalent to promise. Use `scrubDirection=\"vertical\"` when the fields are stacked, as in a width/height pair."},{"label":"OTPField · The six digits from the email","href":"pattern-otpfield-the-six-digits-from-the-email.html","group":"Patterns","description":"One box per character, and paste fills all of them — because nobody types a code they can copy. Masking is for a secret; a verification code is not one, and hiding it only makes it harder to check."},{"label":"Pagination · Walking a long result set","href":"pattern-pagination-walking-a-long-result-set.html","group":"Patterns","description":"The current page is announced, not just highlighted. Previous and Next keep their labels for screen readers even when they show only a chevron — a nameless arrow is a dead end."},{"label":"PasswordField · A password the user can check","href":"pattern-passwordfield-a-password-the-user-can-check.html","group":"Patterns","description":"The reveal exists because typing a password blind is how people get locked out. The button says the action, not the state — Show password, then Hide password — so a screen reader announces what will happen."},{"label":"Popover · The definition behind a number","href":"pattern-popover-the-definition-behind-a-number.html","group":"Patterns","description":"A popover, not a tooltip: the content is rich, it stays open, and the pointer can travel into it to select text. A tooltip that needs a second sentence should have been this."},{"label":"Progress · A job with a known end","href":"pattern-progress-a-job-with-a-known-end.html","group":"Patterns","description":"Determinate only when the total is real. Faking a percentage for something unbounded is worse than the spinner it replaced: it promises an end the system cannot keep."},{"label":"QRCode · Plain code","href":"pattern-qrcode-plain-code.html","group":"Patterns","description":"Round modules and eyes without touching scannability: quiet zone kept, contrast kept."},{"label":"QRCode · Downloadable","href":"pattern-qrcode-downloadable.html","group":"Patterns","description":"The code plus the action that takes it away — the pattern from the target image."},{"label":"QRCode · On a card","href":"pattern-qrcode-on-a-card.html","group":"Patterns","description":"Framed for sharing: a floating surface, the code, and what it points to written out."},{"label":"QRCode · Print safe","href":"pattern-qrcode-print-safe.html","group":"Patterns","description":"Highest error correction for paper, where a scratch is not an if but a when."},{"label":"Radio · One answer out of a few","href":"pattern-radio-one-answer-out-of-a-few.html","group":"Patterns","description":"Radios show every option at once, which is their whole advantage over a select — and their limit: past five or six the list stops being scannable and a select or combobox reads faster."},{"label":"Range · A value with no exact number in mind","href":"pattern-range-a-value-with-no-exact-number-in-mind.html","group":"Patterns","description":"A slider is for approximate values — volume, opacity, a threshold nobody types. When the exact figure matters, a NumberField is honest and a slider is guesswork with a nice handle."},{"label":"SearchField · Narrowing a list as you type","href":"pattern-searchfield-narrowing-a-list-as-you-type.html","group":"Patterns","description":"type=\"search\" so the browser offers its own clear control and history. The glyph is decoration — the accessible name comes from the label, never from the magnifier."},{"label":"Section · The page opening, text beside the proof","href":"pattern-section-the-page-opening-text-beside-the-proof.html","group":"Patterns","description":"variant=\"hero\" is the opening of a page: an eyebrow, the title (the page's h1), a line of text, the buttons, and the image beside it. The title grows with the width of the band, not of the window — 36, then 60 from 768 and 72 from 1024 — and the image sits beside the text from 1024; below that, it goes under. The image takes the width of its column: size it in the app."},{"label":"Section · The page opening, centred","href":"pattern-section-the-page-opening-centred.html","group":"Patterns","description":"align=\"center\" puts everything on the middle line, with the image (if any) under the text. What comes inside the Section goes after the buttons: a short note, a link."},{"label":"Section · The page opening with an e-mail field","href":"pattern-section-the-page-opening-with-an-e-mail-field.html","group":"Patterns","description":"actions takes anything: here, the e-mail field with its button, inside a form. The field keeps its name for the screen reader (aria-label), because the placeholder is not a label."},{"label":"Section · The website footer, dark on a light page","href":"pattern-section-the-website-footer-dark-on-a-light-page.html","group":"Patterns","description":"variant=\"footer\" turns the band into the footer: brand, link columns and the legal line, already inside a Container. It keeps the band's theme, so a dark footer on a light page is theme=\"dark\". On a phone everything stacks."},{"label":"SegmentedControl · Switching the window of a chart","href":"pattern-segmentedcontrol-switching-the-window-of-a-chart.html","group":"Patterns","description":"One dimension, few values, and one is always chosen — that is what separates a segmented control from a button group. Zero selected is not a state it can express, so never use it for a filter that can be cleared."},{"label":"Select · A short, closed list of options","href":"pattern-select-a-short-closed-list-of-options.html","group":"Patterns","description":"The native select is the right answer more often than it gets used: it is the control the platform already knows how to render on a phone, and it needs no portal, no listbox and no keyboard code. Reach for a Combobox when typing beats scrolling."},{"label":"Separator · Between two parts of the same card","href":"pattern-separator-between-two-parts-of-the-same-card.html","group":"Patterns","description":"The line says \"the section above is finished\" without spending a heading on it. Inside a card, where a heading would be too loud and blank space alone reads as an accident."},{"label":"Separator · Between items on one line","href":"pattern-separator-between-items-on-one-line.html","group":"Patterns","description":"`orientation=\"vertical\"` for metadata that shares a row and does not share a meaning. It stretches to the line, so it never reads as a stray character the way a typed pipe does at a different font size."},{"label":"Separator · Grouping a menu without labelling it","href":"pattern-separator-grouping-a-menu-without-labelling-it.html","group":"Patterns","description":"The line groups the destructive action away from the rest so it is not reached by accident. Note what it is not doing: a screen reader hears one flat list, and that is correct — the separation is a pointer affordance, and the wording of the item is what carries the warning."},{"label":"Sidebar · The main navigation of an application","href":"pattern-sidebar-the-main-navigation-of-an-application.html","group":"Patterns","description":"Collapsing keeps the icons and drops the labels — it narrows the column, it does not hide the navigation. On a narrow screen the AppShell turns the same sidebar into a drawer, so there is one navigation, not two."},{"label":"Skeleton · The shape of the content that is coming","href":"pattern-skeleton-the-shape-of-the-content-that-is-coming.html","group":"Patterns","description":"A skeleton only helps when it matches the layout it replaces — otherwise the page jumps when the data lands, which is the exact flicker it was meant to avoid. Use it for content, never for a control."},{"label":"Spinner · Waiting inside a button","href":"pattern-spinner-waiting-inside-a-button.html","group":"Patterns","description":"The label stays while the spinner runs — replacing it with a bare spinner loses what the user is waiting for. Decorative here, because the button already announces itself busy."},{"label":"Status · The state of a service, in a row","href":"pattern-status-the-state-of-a-service-in-a-row.html","group":"Patterns","description":"A coloured dot plus a word. The word is mandatory: colour alone fails for a third of readers, and green and amber are the pair people confuse most."},{"label":"Stepper · Where you are in a sequence","href":"pattern-stepper-where-you-are-in-a-sequence.html","group":"Patterns","description":"Three states in one row: what is done, what you are on, what is left. The current step carries `aria-current=\"step\"`, so the position is announced and not only drawn — a stepper that only draws is a decoration."},{"label":"Stepper · A step that can be skipped","href":"pattern-stepper-a-step-that-can-be-skipped.html","group":"Patterns","description":"`optional` says out loud what a greyed-out label only implies. Marking it is what lets a reader decide to move on, instead of hunting for the field they think they missed."},{"label":"Stepper · A step that failed","href":"pattern-stepper-a-step-that-failed.html","group":"Patterns","description":"`state: \"error\"` keeps the failure in the sequence instead of replacing it with an alert somewhere else. The reader sees which step broke and how far they had got, which is the pair of facts they need to decide whether to fix or restart."},{"label":"Stepper · Going back to a finished step","href":"pattern-stepper-going-back-to-a-finished-step.html","group":"Patterns","description":"`onClick` turns a step into a real button — but only where going back is allowed. Leaving the unreached steps inert is the point: a stepper whose every step is clickable is a tab list wearing the wrong clothes."},{"label":"Switch · Notification settings","href":"pattern-switch-notification-settings.html","group":"Patterns","description":"Flip and it is done. No Save button — that is what makes it a Switch and not a Checkbox."},{"label":"Switch · Feature with state","href":"pattern-switch-feature-with-state.html","group":"Patterns","description":"The switch sets it; a Status reports what the system did with it."},{"label":"Switch · Gated by plan","href":"pattern-switch-gated-by-plan.html","group":"Patterns","description":"Visible so the value is known, disabled so it cannot be flipped — with the reason next to it."},{"label":"Switch · When it waits, it is a Checkbox","href":"pattern-switch-when-it-waits-it-is-a-checkbox.html","group":"Patterns","description":"Same yes-or-no, different moment: this one only takes effect when the form is submitted."},{"label":"Table · With caption","href":"pattern-table-with-caption.html","group":"Patterns","description":"The caption names the table for a screen reader and for the eye — a table with no name is a grid of noise."},{"label":"Table · Operational state","href":"pattern-table-operational-state.html","group":"Patterns","description":"A Status per row instead of a coloured cell: the condition is spelled out, not encoded in a fill."},{"label":"Table · With pagination","href":"pattern-table-with-pagination.html","group":"Patterns","description":"The full collection composition: filter above, selection in the first column, pagination below."},{"label":"Table · View switch","href":"pattern-table-view-switch.html","group":"Patterns","description":"Table or cards for the same data — SegmentedControl switches the view, never the meaning."},{"label":"Table · Row actions","href":"pattern-table-row-actions.html","group":"Patterns","description":"Actions live at the end of the row, ghost so they do not shout over the data."},{"label":"Table · A comparison with groups and the best value","href":"pattern-table-a-comparison-with-groups-and-the-best-value.html","group":"Patterns","description":"Items are columns, specs are rows. Each group of rows is a <tbody> that opens with a band; each row is named by a <th scope=\"row\">. The name column stays put when the table scrolls sideways, and the header stays at the top of the box when it scrolls down. The best value is bold and also says so in text — a Badge, because colour alone tells nothing to someone who cannot see it."},{"label":"Table · Two at a time on a phone","href":"pattern-table-two-at-a-time-on-a-phone.html","group":"Patterns","description":"On a narrow screen the page shows two items, picked with two selects above the table, and `fit` drops the 720px minimum so the two fit with no sideways scroll. Which two is the page's choice; the table only has to fit."},{"label":"Table · Differences only","href":"pattern-table-differences-only.html","group":"Patterns","description":"A switch hides the rows that are the same for every item — the page marks them <tr data-same>, and `differencesOnly` hides them. Removing what does not differ is what makes a long comparison readable."},{"label":"TableOfContents · An index that follows the reading","href":"pattern-tableofcontents-an-index-that-follows-the-reading.html","group":"Patterns","description":"It marks the section in view by itself — pass current only when something else owns that state. Sub-items are one level deep and no more: an index that needs three levels is a document that needs splitting."},{"label":"Tabs · Two readings of the same thing","href":"pattern-tabs-two-readings-of-the-same-thing.html","group":"Patterns","description":"Tabs are for alternative views of one subject, never for steps — a step has an order and a tab does not. If the user must visit all of them, it was a form, not a tab set."},{"label":"Tabs · A column of sections beside the content","href":"pattern-tabs-a-column-of-sections-beside-the-content.html","group":"Patterns","description":"`orientation=\"vertical\"` when the labels are words rather than one-word nouns, or when there are more of them than a row can hold without scrolling. The root becomes a grid and not a row: on a row the panel and the list share a line, and a tall panel would stretch the label column with it."},{"label":"Tabs · When switching a tab costs a request","href":"pattern-tabs-when-switching-a-tab-costs-a-request.html","group":"Patterns","description":"With the default, the arrow key switches the panel along with focus — right when the panel is already there. When each tab fetches, that means crossing five tabs fires five requests. `activateOnFocus={false}` is the APG's manual pattern: the arrow only moves focus, and Enter or Space commits. The choice belongs to the panel's cost, not to taste."},{"label":"Textarea · A description field that grows","href":"pattern-textarea-a-description-field-that-grows.html","group":"Patterns","description":"Rows set the starting height, not the limit. The field keeps the pill radius of every other control, because a text area is still a field — the shape changes only when it becomes a composition box with its own toolbar."},{"label":"Timeline · What happened to this record","href":"pattern-timeline-what-happened-to-this-record.html","group":"Patterns","description":"An ordered list because the order carries meaning: a screen reader announces \"item 2 of 5\" and the reader knows where in the story they are. A stack of divs would say the same words and lose that."},{"label":"Timeline · Entries that carry their own outcome","href":"pattern-timeline-entries-that-carry-their-own-outcome.html","group":"Patterns","description":"`title` takes a node, so an entry can say what it was and how it went in one line. This is the difference between a log the reader has to interpret and an audit trail they can scan."},{"label":"Timeline · The activity panel of a detail page","href":"pattern-timeline-the-activity-panel-of-a-detail-page.html","group":"Patterns","description":"Beside the record, not under it: the timeline answers \"what has been done to this\" while the page answers \"what is this\". Putting it in a card of its own is what keeps the two questions from running together."},{"label":"Timeline · Five styles","href":"pattern-timeline-five-styles.html","group":"Patterns","description":"variant (ADR-0084), all on the rail that runs under the dots and stops at the last one: default (the solid yellow dot), ring (a hollow dot with a yellow ring), latest (muted dots, only the last one yellow with a halo), time (the time in a column on the left) and contrast (dots in the text colour)."},{"label":"Toggle · A button that stays pressed","href":"pattern-toggle-a-button-that-stays-pressed.html","group":"Patterns","description":"Two states the user flips and reads back from the button itself. It is not a Switch: a switch applies a setting, a toggle marks the thing under the cursor."},{"label":"ToggleGroup · The alignment row of an editor","href":"pattern-togglegroup-the-alignment-row-of-an-editor.html","group":"Patterns","description":"Arrow keys walk the group and only one alignment can be true at a time. With multiple it becomes a filter bar where none selected is legitimate — the same component, a different contract."},{"label":"ToggleGroup · The colour of the on state","href":"pattern-togglegroup-the-colour-of-the-on-state.html","group":"Patterns","description":"pressedStyle on the group colours every pressed toggle inside (ADR-0084): brand — the yellow of the primary button, the default — neutral (grey) or contrast (graphite, inverted)."},{"label":"Toolbar · Formatting bar","href":"pattern-toolbar-formatting-bar.html","group":"Patterns","description":"Style and align in named groups, one tab stop for the whole bar."},{"label":"Toolbar · Table header bar","href":"pattern-toolbar-table-header-bar.html","group":"Patterns","description":"Search on one side, actions on the other — the bar that heads a collection."},{"label":"Toolbar · Side rail","href":"pattern-toolbar-side-rail.html","group":"Patterns","description":"A column of tools beside a canvas: up and down navigate, the separator turns with the axis."},{"label":"Toolbar · Undo and redo","href":"pattern-toolbar-undo-and-redo.html","group":"Patterns","description":"History with the unavailable step kept in place, so the arrows never renumber the set."},{"label":"ToolbarButton · A toggle that stays pressed","href":"pattern-toolbarbutton-a-toggle-that-stays-pressed.html","group":"Patterns","description":"`pressed` emits `aria-pressed`, so the state is announced and not only shaded. This is the whole reason a formatting bar uses ToolbarButton instead of a styled div: bold-is-on has to be a fact, not an appearance."},{"label":"ToolbarButton · An unavailable step kept in place","href":"pattern-toolbarbutton-an-unavailable-step-kept-in-place.html","group":"Patterns","description":"`disabled` on the step that cannot run — never removing it. A bar whose buttons come and go renumbers itself under the reader's hand, and the muscle memory that a toolbar exists to build never forms."},{"label":"ToolbarButton · The one action that is not a tool","href":"pattern-toolbarbutton-the-one-action-that-is-not-a-tool.html","group":"Patterns","description":"A toolbar is mostly ghost buttons because they are peers; the moment one of them is the point of the screen it takes a tone of its own. One per bar — a bar of primaries has no primary."},{"label":"Tooltip · Naming an icon-only control","href":"pattern-tooltip-naming-an-icon-only-control.html","group":"Patterns","description":"The IconButton already carries its accessible name; the tip is what shows that name to everyone else. Two mechanisms, one string — which is why the label and the tip must say the same thing, never two different things."},{"label":"Tooltip · Why a control is unavailable","href":"pattern-tooltip-why-a-control-is-unavailable.html","group":"Patterns","description":"A disabled button says no and not why, and a disabled element does not receive focus — so the tip goes on a wrapper that does. Without that the explanation exists only for a mouse, which is the failure this pattern is here to avoid."},{"label":"Tooltip · Spelling out an abbreviated column","href":"pattern-tooltip-spelling-out-an-abbreviated-column.html","group":"Patterns","description":"`side=\"right\"` when the trigger sits in a narrow column and a tip above would cover the row being read. The header still has to make sense without the tip: P95 is the label, the tip only expands it."},{"label":"Topbar · The bar that carries the brand and the global actions","href":"pattern-topbar-the-bar-that-carries-the-brand-and-the-global-actions.html","group":"Patterns","description":"Brand on the left, actions on the right, and nothing in between that belongs to a single page. The floating variant sits on the content; flush joins the page — pick one per application, not per screen."},{"label":"TreeView · A source tree beside the editor","href":"pattern-treeview-a-source-tree-beside-the-editor.html","group":"Patterns","description":"Arrow keys walk it, Right opens a branch and Left closes it — the shape people already know from every file explorer. Only the branch the user is working in starts open."},{"label":"Sign-in panel","href":"block-sign-in-panel.html","group":"Blocks","description":"Card with credentials, an inline error slot and one primary action. No password is ever pre-filled."},{"label":"Settings form","href":"block-settings-form.html","group":"Blocks","description":"One column of fields, toggles grouped at the end, a single primary action and a ghost escape."},{"label":"Members table","href":"block-members-table.html","group":"Blocks","description":"The full collection surface: filter, selection, status per row, row actions and pagination."},{"label":"Empty project state","href":"block-empty-project-state.html","group":"Blocks","description":"First run with nothing to show: says what is missing, why, and the one action that fixes it."},{"label":"Stats row","href":"block-stats-row.html","group":"Blocks","description":"Four numbers of equal weight above a dashboard. Trend beside the value, never a chart without a number."},{"label":"Pricing row","href":"block-pricing-row.html","group":"Blocks","description":"Three plans side by side, the recommended one marked by a Badge — not by a bigger box."},{"label":"Activity panel","href":"block-activity-panel.html","group":"Blocks","description":"Who did what, when — identity line, ordered history and the unread count in one surface."},{"label":"Run session panel","href":"block-run-session-panel.html","group":"Blocks","description":"One run, end to end: what state it is in, the turns, the tool it is calling, where it resumes from, the receipt it already owns, and only the actions the run can take right now. The approval gate takes the place of the actions while a person has to decide."},{"label":"Review compare","href":"block-review-compare.html","group":"Blocks","description":"Nothing changes until someone sees what would change: the difference, the checks that ran on it, the one decision the change can take right now, and the receipt that apply writes and rollback points back to. Additions and deletions are text, so the diff reads the same without colour."},{"label":"Resource workbench","href":"block-resource-workbench.html","group":"Blocks","description":"Where resources come from, what is in there, what the selected one is, what is in flight right now, where it all came from, and only the actions this phase allows. The transfer says its phase and its percent in words, so the bar is never the only thing carrying the news."},{"label":"Analytics workbench","href":"block-analytics-workbench.html","group":"Blocks","description":"The period, the filters, the segments and the export scope on one line; the number, the curve and the same curve as a table below it. The table is not a fallback and not a tab: a chart without its numbers excludes whoever cannot read the chart."},{"label":"Transaction flow","href":"block-transaction-flow.html","group":"Blocks","description":"What is being bought, what it adds up to, which saved method pays for it, and — before anything is charged — the consequence in one sentence. Every terminal result leaves an immutable receipt with the idempotency key, so a double click has an answer. A refund points back at that receipt instead of erasing it."},{"label":"Device control","href":"block-device-control.html","group":"Blocks","description":"One device inside its fleet: what it is, what it is reading right now — with the time and the quality of each reading — what a command would reach and what it would do, the calibration with its default and a way back, and who touched it last. Live readings can be paused, and a firmware update asks before it drops the equipment."},{"label":"Media library","href":"block-media-library.html","group":"Blocks","description":"One selection shared by the gallery, the detail and the player — never three strings that happen to match. The resume position is a number, the optional capabilities say which ones exist, and the queue can be reordered without touching what is playing. The transport lives in the player and nowhere else."},{"label":"Visual builder","href":"block-visual-builder.html","group":"Blocks","description":"A canvas with an ordered outline that says the same thing, so building never requires a mouse: add from the palette, move in the outline, connect in the inspector. Credentials appear as references and never as values. Undo and redo sit beside whatever the state machine actually allows right now."},{"label":"Public site","href":"recipe-public-site.html","group":"Recipes"},{"label":"Docs · CMS","href":"recipe-docs-cms.html","group":"Recipes"},{"label":"SaaS · admin","href":"recipe-saas-admin.html","group":"Recipes"},{"label":"Dashboard · BI","href":"recipe-dashboard-bi.html","group":"Recipes"},{"label":"Catalog · gallery","href":"recipe-catalog-gallery.html","group":"Recipes"},{"label":"Media · streaming","href":"recipe-media-streaming.html","group":"Recipes"},{"label":"Automation · workflow","href":"recipe-workflow-automation.html","group":"Recipes"},{"label":"Developer tools","href":"recipe-developer-tools.html","group":"Recipes"},{"label":"Files · cloud","href":"recipe-file-cloud.html","group":"Recipes"},{"label":"Messaging · social","href":"recipe-messaging-social.html","group":"Recipes"},{"label":"Commerce · finance","href":"recipe-commerce-finance.html","group":"Recipes"},{"label":"Booking · calendar","href":"recipe-booking-calendar.html","group":"Recipes"},{"label":"Maps · logistics","href":"recipe-maps-logistics.html","group":"Recipes"},{"label":"IoT · control","href":"recipe-iot-control.html","group":"Recipes"},{"label":"Agents · AI","href":"recipe-agent-ai.html","group":"Recipes"},{"label":"Projects · CRM/ERP","href":"recipe-project-crm-erp.html","group":"Recipes"},{"label":"Education","href":"recipe-education.html","group":"Recipes"},{"label":"Personal productivity","href":"recipe-personal-productivity.html","group":"Recipes"},{"label":"Mobile · PWA","href":"recipe-mobile-pwa.html","group":"Recipes"},{"label":"Support · service","href":"recipe-support-service.html","group":"Recipes"},{"label":"Regulated records","href":"recipe-regulated-records.html","group":"Recipes"},{"label":"Creative workspace","href":"recipe-creative-workspace.html","group":"Recipes"},{"label":"Observability · ops","href":"recipe-observability-ops.html","group":"Recipes"}];
